programs.sol:
"""A token-local detector for the spelling 'um', not numerical meaning.
Short fragments and -um endings respond strongly; longer words usually weakly.
Number, volume, sum, and drum word families are distinguished. Leading spaces
and capitalization change the response. Cyrillic ум is a weaker analogue.
"""
import math

READS = ()

# A consonant followed by -um: rhyme fragments, rather than full-word meanings.
UM_ENDINGS = {'r': 5.4, 'c': 4.1, 'd': 4.0, 'b': 4.0, 't': 3.9,
              'h': 3.4, 'g': 2.8, 'l': 2.8, 'z': 2.0, 'y': 2.0, 'm': 1.4}


def spelling_score(raw):
    word = raw.strip().strip('.,:;/-_()[]{}<>\"\'')
    s = word.lower()
    spaced, title = raw[:1].isspace(), word.istitle()
    if 'ум' in s:
        return 2.8 if s == 'ум' else 1.5 if len(s) <= 4 else 0.4
    if 'um' not in s:
        return 0.0
    if s == 'um':
        return 1.6 if spaced or title else 4.2 if word.isupper() else 4.6
    if s.startswith('um'):
        if spaced:
            return 0.8
        if s == 'ums':
            return 3.6
        if s.startswith(('umm', 'umid')) or s in ('umat', 'umor'):
            return 2.3
        if len(s) == 3 and s[2] in 'aiou':
            return 2.5
        return 1.5 * math.exp(-0.45 * max(0, len(s) - 3))
    if s in ('num', 'enum'):
        if raw[:1] in '([{=:_-':
            return 2.4
        if s == 'enum' and not spaced and not title:
            return 4.5
        return 3.8 if spaced and title else 2.6 if spaced else 3.2
    if s == 'sum':
        if raw.startswith('.'):
            return 1.8
        return 2.4 if word.isupper() and not spaced else 1.3
    if s.startswith('drum'):
        return 4.1 if s.endswith('s') else 3.6 if len(s) == 4 else 2.0
    if s.startswith('cumul'):
        return 2.5
    if s.endswith('um'):
        if s.endswith('ium'):
            return 1.1 if len(s) <= 5 and not spaced else 0.2
        if len(s) == 3:
            return UM_ENDINGS.get(s[0], 2.8)
        if len(s) == 4 and s[-3:] in ('rum', 'tum', 'cum', 'lum'):
            if s == 'ulum':
                return 1.5
            if s.endswith('rum'):
                return 4.5
            if s.endswith('tum'):
                return 4.8
            return UM_ENDINGS[s[-3]]
        if s == 'forum':
            return 3.8 if title and spaced else 3.2
        if s in ('serum', 'quantum', 'datum', 'volum'):
            return 2.4
        if s == 'circum':
            return 1.3
        return 0.2 + 1.3 * math.exp(-0.8 * max(0, len(s) - 4))
    if 'number' in s:
        return 1.25 if title else 0.96
    if 'volume' in s:
        return 0.8 if title else 1.0
    if s.startswith(('sum', 'resum', 'enumer', 'numer', 'accumul')):
        return 0.8
    if s.startswith(('human', 'column', 'assum', 'consum')):
        return 0.2
    if s.startswith(('jump', 'trump')):
        return 0.3
    if s.startswith('pump'):
        return 0.6
    if s.startswith('tumor'):
        return 1.2
    return 1.5 * math.exp(-0.4 * max(0, len(s) - 4))


def step(carry, prefix, upstream):
    return None, float(spelling_score(prefix.token_strings[-1]))

programs.haiku:
"""Layer-0 MLP down-projection component 5376: an "um" spelling detector.

It reads the current token alone. It is silent (0) on almost every token and
fires on tokens whose spelling contains the letters "u" then "m" (or "num"),
i.e. the sound "um":
  - strongest (about 4) on a bare "um"/"num"-type token with no leading space,
    e.g. "um", "_num", "Forum", "hum", Cyrillic "ум";
  - moderate (about 1.5) when "um"/"num" begins or ends a word piece, e.g. " number",
    " volume", " sum", "uma", "umb";
  - weak (about 0.4) when "um" sits inside a longer word, e.g. "human", "column",
    "museum", "minimum";
  - 0 otherwise.
The values are the variance-fit scale of the tiers, not per-token numbers.
"""

READS = ()

BARE_UM = {"um", "num", "forum", "hum", "lum", "gum", "rum", "cum", "zum", "ум", "дум", "üm"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    core = token.strip().strip("_.").lower()
    if core in BARE_UM:
        value = 4.0 if not token[:1].isspace() else 2.0
    elif "um" in core or "num" in core or "ум" in core or "üm" in core:
        if core.startswith(("um", "num")) or core.endswith(("um", "num")):
            value = 1.5
        else:
            value = 0.4
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate the positive response to the spelling chunk "um".

The standalone token, number-like `num`, and `rum` pieces get different
typical strengths; unrelated tokens default to zero.
"""

READS: tuple[str, ...] = ()


def step(carry, prefix, upstream):
    folded = prefix.token_strings[-1].casefold()
    if folded.strip() == "um":
        return None, 3.9
    if "numb" in folded:
        return None, 1.11
    if "num" in folded:
        return None, 1.27
    if "rum" in folded:
        return None, 1.82
    if "um" in folded:
        return None, 0.85
    return None, 0.0

programs.sol:
"""Two lexical signals: document/header labels (+), and z-like spelling (-).

Header, footer, metadata, and end-of-text have positive responses; headlines
and Chinese head/top characters are weaker positive cues. Short
z-initial pieces have negative responses, especially capitalized ones and
'ze'. A z at the preceding token boundary reinforces a continuing word.
At row/document starts, isolated z-like letters have a stronger response.
End-of-text rises toward its usual positive level with document position.
These are approximate spelling rules, not a general semantic classifier.
"""
READS = ()
Z_LETTERS = 'zзز'
HEAD_OR_TOP = {'头', '頭', '顶', '頂'}


def lexical(text):
    word = text.strip().strip('._/\\-*=<>$(),:;')
    lower = word.lower()
    spaced = text[:1].isspace()
    if lower == 'header':
        if word.isupper():
            return 3.4
        if text == word:
            return 4.15
        if spaced and word[:1].isupper():
            return 3.95
        return 3.75 if text.startswith('_') else 3.4
    if lower == 'headers':
        if word.isupper():
            return 1.5
        return 2.65 if spaced and word[:1].isupper() else 2.05
    if lower in {'footer', 'footers'}:
        return 1.9
    if lower == 'metadata':
        return 1.0
    if 'header' in lower:
        return 1.6
    if lower in {'headline', 'headlines'}:
        return 0.6
    if word in HEAD_OR_TOP:
        return 0.7 if word == '头' else 0.5
    if lower in {'zone', 'zones', 'zona'}:
        return -0.7
    if lower == 'z':
        return -0.82 if spaced else (-0.7 if word.isupper() else -0.52)
    if lower == 'ze':
        return -1.22 if word[:1].isupper() else (-1.0 if spaced else -0.72)
    if lower.startswith('z'):
        if len(lower) <= 3:
            return -0.45 if word[:1].isupper() else -0.3
        return -0.24 if spaced and word[:1].isupper() else -0.07
    if lower in {'з', 'ز'}:
        return -0.2 if spaced else -0.05
    if 'z' in lower and len(lower) <= 3:
        if lower.endswith('tz'):
            return -0.4
        return -0.27 if 'zz' in lower else -0.07
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    # A packed row may start a new document between consecutive tokens.
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    value = lexical(text)
    if text == '<|endoftext|>':
        value = 1.88 - 0.63 / (position + 1) ** 0.8
    elif position == 0:
        word = text.strip().strip('._/\\-*=<>$(),:;')
        if word.lower() == 'z':
            value = -3.3 if word.isupper() else -2.7
        elif word.lower() in {'з', 'ز'}:
            value = -1.3
        elif 'z' in word.lower() and len(word) <= 3:
            value *= 3.0
    elif text[:1].isalpha() and previous:
        prev = previous.strip().lower()
        if prev.endswith(tuple(Z_LETTERS)):
            if any(c in text.lower() for c in Z_LETTERS):
                repeated = text.lower().startswith(tuple(Z_LETTERS))
                value -= 1.5 if repeated and len(prev) <= 3 else 0.9
            else:
                value -= 0.32 if prev in Z_LETTERS else 0.08
    return (doc, position + 1, text), value

