"""Use a few visible token markers as a rough activation estimate."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    lower = token.lower()
    if token == "<|endoftext|>":
        return None, 2.0
    if "header" in lower:
        return None, 2.5
    if "z" in lower:
        return None, -0.5
    return None, 0.0

programs.sol:
"""Education vocabulary, with smaller signals for learning and upbringing.

This is a current-token word-class detector, including education-related
fragments and translations.  State handles split words and short
school/education phrases; it resets per document.
It does not attempt to model the many small responses on unrelated words.
"""
READS = ()

TEACHERS = set('teacher teachers academic academics'.split())
PUPILS = set('student students pupil pupils kids classroom classrooms '
             'curriculum academy academia preschool teenager teenagers'.split())
LEARNING = set('learn learning learned learner learners informed informative '
               'college colleges university universities campus tuition '
               'courses lesson lessons taught intellectual scholarship '
               'scholarships undergraduate'.split())
UPBRINGING = set('child children parents childhood youth young training '
                 'teach teaches teaching teachings graduated graduation '
                 'alumni agriculture cultivation'.split())
SCHOOL_LIFE = set('class classes course study studies studying degree doctoral '
                  'faculty professor professors instructor instructors '
                  'grade grades homework exam exams attendance library '
                  'libraries textbook textbooks program programs '
                  'institution institutions'.split())
FAMILY = set('mother father parent family parental maternal boy boys girl '
             'girls daughter daughters sons'.split())


def signal(raw):
    word = raw.strip().strip('._-/').lower()
    if word == 'educated':
        return 6.0
    if word.startswith('educator') or word in {'educ', 'éduc'}:
        return 4.5
    if word.startswith(('education', 'educate', 'educating')):
        return 5.2
    if word == 'edu':
        return 2.9 if raw.startswith(' ') else 1.5
    if word == 'ducation' or word.startswith(('educa', 'éduca')):
        return 3.6
    if word in {'school', 'chool'}:
        return 1.95
    if word in {'schools', 'schooling', 'homeschool'}:
        return 2.4
    for words, value in ((TEACHERS, 1.85), (PUPILS, 1.25), (LEARNING, 0.75),
                         (UPBRINGING, 0.6), (SCHOOL_LIFE, 0.35), (FAMILY, 0.3)):
        if word in words:
            return value
    if word in {'agricultural', 'cultivated', 'scho', 'acad'}:
        return 1.1

    # Education / rearing, school, pupils / teachers, and learning in East Asia.
    if word in {'教育', '育'}:
        return 4.8
    if '教育' in word:
        return 2.5
    if word in {'교육', '육'}:
        return 3.1
    if word in {'学校', '學校'}:
        return 3.0
    if '校' in word:
        return 1.7
    if any(w in word for w in ('学生', '學生', '学员', '老師', '老师',
                               '教师', '教師', '孩子', '子ども', '학교')):
        return 1.35
    if word in {'小学', '小學', '中学', '塾', '同学们', '同學們'}:
        return 1.3
    if word in {'学习', '學習', '教学', '教學', '培训', '培养', '家长',
                '儿童', '课', '課', '訓', '训', '的学习', '女生', '男生'}:
        return 0.8
    if word in {'学', '學', '大学', '大學', '学院', '园', '園', '修', '班', '父母'}:
        return 0.55
    if word.startswith(('школ', 'учеб', 'обуч', 'schüler')):
        return 1.5
    if word.startswith(('schul', 'lehr', 'bildung')):
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    value = signal(raw)
    prev_word = previous.strip().lower()
    if prev_word in {'educ', 'éduc'} and raw.lower().startswith('at'):
        value = max(value, 4.2 if raw.lower() in {'ate', 'ates'} else 3.4)
    if prev_word in {'school', 'chool'}:
        if raw in {'s', 'ing'}:
            value = max(value, 1.1)
        elif raw.lower() == ' district':
            value = max(value, 0.9)
    if raw == ' of' and signal(previous) >= 1.8:
        value += 0.33 * signal(previous)
    return (doc, raw), float(value)

programs.luna:
"""Respond to education, schools, and the people around learning.

The strongest cue is education vocabulary, followed by school words. Learners,
children, and teaching-related terms receive smaller, concept-sized predictions.
"""
READS = ()

