programs.sol:
"""Recognize chemical -yl spellings, including split suffixes.

The main negative response is to the isolated suffix ``yl`` or ``ethyl``;
chemical roots immediately before it strengthen the response. Longer -yl
fragments, other chemical endings and acid/group vocabulary respond less.
Chat message endings have a small, separate positive response. This is a
spelling-based approximation, not a chemical parser: names can trigger it too.
The isolated suffixes respond more strongly at the start of a document.
Weaker rules cover chemical characters in other scripts and spelling lookalikes.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, word = '', ''
    else:
        previous, word = carry[1:]
    s = token.strip().lower()
    prev = previous.strip().lower()
    # Keep just the current alphabetic word, for suffixes crossing token edges.
    if token[:1].isspace() or not token.isalpha():
        word = ''
    root = word.lower()
    next_word = (word + token)[-60:] if token.isalpha() else s
    value = 0.0

    if token == '<|im_end|>':
        value = 0.37
    elif s == 'yl':
        value = -5.1 if token == 'YL' else -5.3
        if prev == '-':
            value = -6.1
        # Ethyl/benzyl, alkyl/propyl/phenyl, then other substituent roots.
        if root.endswith(('eth', 'benz')):
            value = -9.1
        elif root.endswith(('alk', 'prop', 'phen')):
            value = -8.1
        elif root.endswith(('vin', 'ox', 'but', 'ac', 'yn')):
            value = -7.5
        elif root.endswith((
            'phosphatid', 'oct', 'hex', 'pent', 'am', 'in', 'ol', 'ut'
        )):
            value = -7.0
    elif s == 'ethyl':
        value = -5.4
        if prev.endswith(('xy', 'trim', 'ym')):
            value = -7.7
        elif prev.endswith(('dim', 'ino', 'am')):
            value = -6.2
        elif prev == 'fo':
            value = -4.4
    elif s in ('etyl', 'methyl', 'vinyl', 'anyl'):
        value = -4.1 if s != 'etyl' else -4.7
    elif s in ('ethylene', 'ylene', 'ylation'):
        value = -2.8
    elif token in ('yla', 'yle', 'yles', 'yll', 'ylan', 'eryl', 'aryl'):
        value = -2.1
    elif token in ('ylv', 'ylum', 'yled', 'ylim', 'ylon'):
        value = -1.0
    elif token in ('l', 'L'):
        value = -0.2
        if prev.endswith(('oy', 'ony', 'acy', 'icy')):
            value = -4.6
        elif prev.endswith('y'):
            value = -3.0
    elif token in ('ll', 'lo', 'la', 'le', 'lam') and (
        prev.endswith('y') or root.endswith('cyc')
    ):
        value = -1.2
    elif token in ('lation', 'lated', 'late') and root.endswith(('y', 'yl')):
        value = -1.5
    elif s in ('acid', 'acids'):
        value = -0.9
        if prev == 'fatty':
            value = -2.7
        elif prev in ('amino', 'lic', 'amic'):
            value = -1.15
    elif s in ('group', 'groups'):
        value = -0.3 if s == 'groups' else 0.0
        if prev.endswith(('yl', 'ylene')):
            value = -2.7 if prev == 'methyl' else -1.5
        elif prev in ('functional', 'amino', 'organic', 'aromatic'):
            value = -1.1
    elif s == '基':
        value = -3.0
        # Chinese alkyl/acyl and oxygen-containing functional groups.
        if prev and prev[-1] in '甲乙丙丁戊己庚辛壬癸羟羰羧烷胺氧酰':
            value = -7.0
    elif token in ('ил', 'イル'):
        value = -1.1
    elif s == '酸':
        value = -0.7
    elif s in ('basis', 'cylinder', 'cylinders', 'cylindrical'):
        value = -0.8
    elif token in ('anol', 'dehyde', 'rylic'):
        value = -1.0
    elif s in ('meth', 'acet', 'eth', 'benz', 'chlor'):
        value = -0.7 if token.startswith(' ') else -0.3
    elif s == 'oxy':
        value = -2.5 if root.endswith(('eth', 'meth', 'prop', 'poly')) else -1.0
    elif token == 'xy':
        value = -2.0 if root.endswith('hydro') else -0.35
    elif token == 'col' and root.endswith('gly'):
        value = -1.1
    elif token.startswith('y') and len(token) in (2, 3, 4, 5) and (
        token[1] in 'csrnm'
    ):
        value = -0.4
    elif token in ('il', 'ly', 'л', 'ol'):
        value = -0.2
    if not previous:
        if token in ('yl', 'ethyl'):
            value = -9.2
        elif token == 'YL':
            value = -7.5
    return (doc, token, next_word), float(value)

programs.luna:
"""Mark message endings and the recurring 'yl' word-piece signal in the token stream."""
READS = ()


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    if piece == "<|im_end|>":
        return None, 0.37

    text = piece.strip().lower()
    if text == "yl":
        return None, -7.8
    if text.endswith("yl"):
        return None, -5.4
    if text == "l":
        return None, -0.25
    return None, 0.0

programs.haiku:
"""Draft 5: nouns for a stored collection of things (library, database, repository, ...).

Layer-0 MLP unit that goes negative on words naming a place or set where many items are
kept: library (and 库/庫, Chinese for library or warehouse) most strongly; then database,
DB, repository, reservoir, archive; then collection, pool, registry, dataset, battery,
catalog, inventory, gallery, treasury and similar. Right after such a word, 'of' (as in
'Library of Congress') is also negative. Everything else is near zero.
Its value is the token's own word, so the program reads only the newest token (and the
previous value, for the 'of' rule).
"""

READS = ()

# (substring of the lowercased token, activation)
LIBRARY = {"librar": -3.0, "库": -4.0, "庫": -3.4, "ibrary": -3.0}
STORE = {"database": -2.2, "数据库": -2.3, "repositor": -1.8, "reservoir": -1.8,
         "archiv": -1.3, "elib": -1.4, "_lib": -1.3, "池": -1.0, "收藏": -1.1}
COLLECTION = {"collection": -0.9, "pool": -0.9, "registry": -0.9, "dataset": -0.8,
              "battery": -0.8, "电池": -0.8, "catalog": -0.8, "inventory": -0.6,
              "gallery": -0.6, "treasury": -0.8, "portfolio": -0.5, "vocab": -0.5,
              "bank": -0.4, "museum": -0.4, "deck": -0.6, "藏": -0.7, "典": -0.5}
EXACT = {"db": -1.2, "lib": -0.3, "repo": -1.0}   # short forms, matched as whole words


def _value(token):
    w = token.strip().lower()
    if w in EXACT:
        return EXACT[w]
    for table in (LIBRARY, STORE, COLLECTION):
        for root, v in table.items():
            if root in w:
                return v
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    prev = carry or 0.0          # the previous token's value
    if token == "of" and prev < -0.4:
        v = 0.4 * prev           # 'of' right after a store word: 'Library of ...'
    else:
        v = _value(token)
    return v, float(v)

programs.luna:
"""Use stronger negative estimates for software and data libraries."""

READS = ()

LIBRARY_WORDS = {"library", "libraries"}
REPOSITORY_WORDS = {"repository", "repositories", "repo", "repos"}
DATABASE_WORDS = {"database", "databases", "db"}
DATASET_WORDS = {"dataset", "datasets"}
COLLECTION_WORDS = {
    "collection", "collections", "registry", "inventory", "archive", "archives",
    "catalog", "catalogue", "corpus", "encyclopedia", "集合", "仓库", "大全", "viện",
}
STORAGE_WORDS = {
    "pool", "deck", "portfolio", "reservoir", "warehouse", "battery", "commons",
    "toolkit", "folder", "directory", "store", "hub", "jar", "vault", "treasury",
    "stack", "gallery", "universe", "vast", "considerable",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    token = token.strip(".,:;!?()[]{}\"'`*_-/\\")
    if token.endswith("positories"):
        return None, -1.5
    if token in LIBRARY_WORDS:
        return None, -2.0
    if token in REPOSITORY_WORDS or token in DATABASE_WORDS:
        return None, -1.5
    if token in DATASET_WORDS:
        return None, -0.8
    if token in COLLECTION_WORDS:
        return None, -0.5
    if token in STORAGE_WORDS:
        return None, -0.3
    return None, 0.0

programs.sol:
"""A lexical detector for existence and quantification, not a truth test.

Large negative values mark exist-words, Chinese 存在, and ∀/∃ (including
LaTeX forall/exists). Related presence, generality, and familiarity words
have weaker values. Word endings and a few prepositions continue the response.
Unrecognized tokens contribute zero; document boundaries clear the memory.
"""
READS = ()

EXIST_FORMS = {
    'exist': -3.3, 'exists': -3.9, 'existed': -3.0,
    'existence': -3.0, 'existing': -1.3, 'existent': -1.55,
    'nonexistent': -1.1, 'existential': -2.4, 'existe': -2.55,
}
RELATED = {
    'presence': -1.3, 'familiar': -0.73, 'familiarity': -0.38,
    'overall': -0.75, 'universal': -0.9, 'universally': -1.4,
    'eternal': -0.6, 'everywhere': -0.4, 'entity': -0.36,
    'entities': -0.28, 'ontology': -0.36,
}
# Translations or stems: existence, present, universal, overall, familiar.
TRANSLATIONS = {
    '存': -1.3, '존재': -3.15, 'существ': -0.82,
    'существует': -1.4, 'есть': -0.4, 'vorhand': -1.85,
    'وجود': -0.84, 'موجود': -1.1, 'налич': -1.1,
    '普遍': -1.94, '整体': -0.78, '熟': -0.78,
    '恒': -0.65, '永恒': -0.9, '成立': -1.1,
}
# Tokens completing an exist-word, e.g. Exist + ence.
EXIST_ENDINGS = {
    'ence': -2.6, 'ent': -1.6, 'ential': -1.7,
    'encia': -1.2, 'ência': -1.4, 'em': -1.3, 'en': -1.1,
    'ir': -0.8, 'ing': -1.0,
}


def lexical_value(token):
    raw = token.strip()
    word = raw.lstrip('._-(').lower()
    if raw == 'forall':
        return -6.45
    if raw == '∀':
        return -6.0 if token[:1].isspace() else -6.6
    if raw == '∃':
        return -5.85
    if word in EXIST_FORMS:
        value = EXIST_FORMS[word]
        if word == 'exists':
            if raw.isupper():
                value = -2.7
            elif raw.startswith('.'):
                value = -3.4
            elif raw.startswith('_'):
                value = -4.1
            elif raw == 'exists' and not token[:1].isspace():
                value = -5.1
        elif word == 'exist' and not token[:1].isspace():
            value = -2.9
        elif word == 'existence' and not token[:1].isspace():
            value = -1.6
        return value
    if word in ('existssync', 'notexist'):
        return -2.3
    if raw == '存在':
        return -4.5
    if raw == '不存在':
        return -4.1
    if '存在' in raw:
        return -1.9 if raw == '存在于' else -3.4
    if word in ('isset', 'ispresent'):
        return -1.3
    if raw.endswith('foreach'):
        return -0.75
    return RELATED.get(word, TRANSLATIONS.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical_value(token)
    if '\ufffd' in token and previous:
        # A split UTF-8 symbol becomes recognizable on its final byte.
        char = prefix.text_prefixes[-1][-1:]
        if char == '存':
            value = -3.25
            word = char
        elif char == '∃':
            value = -6.95
        elif char == '∀':
            value = -6.0
    if word == 'exists' and previous.endswith('\\'):
        value = -6.7  # LaTeX's existential quantifier
    if previous.lstrip('._-') == 'exist' and not token[:1].isspace():
        if word in EXIST_ENDINGS:
            value = EXIST_ENDINGS[word]
            word = 'exist' + word
    if previous == 'vorhand' and word == 'en':
        value = -0.9
    if previous == 'существ' and word in ('уют', 'ующ', 'овал', 'ование'):
        value = -1.5 if word == 'уют' else -0.65
    if word == '在' and previous == '存':
        value = -3.7
        word = '存在'
    if word == 'of':
        if previous == 'existence':
            value = -2.1
        elif previous == 'presence':
            value = -0.93
    if previous in ('familiar', 'familiarity'):
        if word == 'with':
            value = -0.85 if previous == 'familiar' else -0.4
        elif word == 'to':
            value = -0.35
    return (doc, word), float(value)

programs.haiku:
"""Layer 0 MLP down-projection component 5384: an "existence" detector.

The component is a token detector for existence and universality. Its activation is
negative (more negative = stronger) on the current token when that token is:
- the universal quantifier "forall" / "∀" (about -6.5);
- a form of the verb or noun "exist" (exists, exist, existence, existed, _exists,
  Exists, and the Chinese 存在): about -3 to -4.5;
- "existing", "existent" and "presence" (about -1.3);
- a weaker group of words about universality, permanence or presence
  ("universal", "普遍", "overall", "everywhere", "absent", "eternal", "恒", "vorhanden",
  "成立", "familiar"), about -0.5 to -1.9.
Every other token predicts 0. The activation depends almost only on the current token,
so the program reads just the newest token's text (decoded alone) and keeps no state.
"""

READS = ()

# Weaker words about universality, permanence and presence, with rough strengths.
WEAK = {
    "universal": -0.9, "普遍": -1.9, "overall": -0.7, "everywhere": -0.4,
    "absent": -0.5, "eternal": -0.6, "恒": -0.7, "vorhanden": -1.7,
    "成立": -1.0, "familiar": -0.75,
}


def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().lower()
    if "forall" in w or w == "∀":
        value = -6.5
    elif "存在" in w:
        value = -4.5
    elif "exist" in w:
        # "existing", "existent" and "nonexistent" are weaker than the verb and noun forms
        value = -1.3 if w.endswith(("ing", "ent")) else -3.5
    elif w == "presence":
        value = -1.3
    else:
        value = WEAK.get(w, 0.0)
    return carry, value

programs.luna:
"""Use word cues for existence and presence.

English exist- forms get the strongest negative guesses; presence, Russian
существ-, Chinese 存, and a few related scope words get smaller ones. The cue
can continue to "of" after existence/presence, or to a Russian suffix. Other
tokens receive a tiny negative background guess."""

READS = ()


def _word(token):
    return token.lower().strip().strip(".,!?;:()[]{}\"'`*_~")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = _word(token)
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = _word(prefix.token_strings[-2])

    if "existence" in word:
        return None, -3.1
    if "existing" in word:
        return None, -1.25
    if "existed" in word:
        return None, -3.3
    if "exists" in word or word == "exist":
        return None, -3.6
    if "existent" in word:
        return None, -1.5
    if "exist" in word:
        return None, -3.0

    if "presence" in word:
        return None, -1.25
    # Broad-scope words are weaker neighbors of the existence signal.
    if word in {"overall", "universal", "eternal", "undeniable"}:
        return None, -0.7
    if word in {"familiar", "familiarity"}:
        return None, -0.65
    if word == "with" and ("familiar" in previous or "familiarity" in previous):
        return None, -0.7
    if word == "of" and ("existence" in previous or "presence" in previous):
        return None, -2.4 if "existence" in previous else -0.95
    if "существ" in word:
        return None, -0.8
    if "существ" in previous and "ющ" in word:
        return None, -0.68
    if "存" in token:
        return None, -1.5
    return None, -0.00227

programs.sol:
"""Recognize t spellings split across tokens, especially a doubled t.

Short t-ending and t-starting fragments give a large positive response;
long fragments and a change to a capitalized word weaken it. The digraph
th is weaker than other t continuations. Escaped tabs are a separate case.
Other consonant continuations are usually negative, especially h, s, v,
and w. These are approximate spelling rules, not a word or token lookup.
"""
READS = ()
VOWELS = frozenset('aeiouyáéíóúäëïöüаеиоуыэюя')
MID_LOW_VOWELS = frozenset('aeoáéóäëöаэео')


def consonant_response(token, previous):
    """The small, mostly negative side of the t-boundary response."""
    onset = token[0].lower()
    length = len(token)
    cluster = len(previous) > 1 and previous[-2].isalpha() \
        and previous[-2].lower() not in VOWELS
    if onset == 'h':
        value = -0.95
    elif onset == 'w':
        value = -1.2 if length == 1 else -0.6
    elif onset == 'v':
        value = -0.6
    elif onset == 's':
        value = -0.7 if 1 < length < 4 else -0.25
    elif onset == 'k':
        value = -0.5
    elif onset in 'bpq':
        value = -0.4
    elif onset in 'fcrlnбвкс':
        value = -0.2
    elif onset == 'z':
        return 0.22
    else:
        return 0.0
    if cluster:
        value *= 0.3 if onset in 'brl' else 0.75
    if length >= 6:
        value *= 0.2
    elif length >= 4:
        value *= 0.7
    if token[0].isupper() and not token.isupper():
        value *= 0.2
    return value


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = 0.22 if token == r'\t' else 0.0
    if previous.lower().endswith(('t', 'т')) and token:
        if token == r'\t':
            value = 1.37
        elif token.startswith(('t', 'т')) or (
            token.startswith('T') and token.isupper()
            and previous.endswith('T')
        ):
            value = 3.0 - 0.27 * (len(token) - 1) \
                - 0.27 * (len(previous.strip()) - 1)
            if len(previous) > 1 and previous[-2].lower() in MID_LOW_VOWELS:
                value += 0.44
            if token.lower().startswith('th'):
                value -= 0.58
            value = max(0.1, value)
        elif token.startswith('T'):
            value = 0.35
        elif token.startswith((' t', ' T')):
            value = 0.65 if len(token) == 2 else (
                0.12 if len(token) == 3 else 0.04
            )
        elif token[0].isalpha():
            value = consonant_response(token, previous)
        elif token.lstrip('-.*').startswith(('t', 'T')):
            value = 1.3 if token.startswith('*') else 0.2
    return (doc, token), float(value)

"""A negative pulse on words meaning case, situation, or circumstance.

Conditions, occasions, and uses have weaker pulses. Common translations,
inflections, programming spellings, and related characters are included. 'Case' is stronger in
conditional phrases, but weaker in indentation and letter-case terminology.
The following 'of' or 'where' carries part of a pulse. Other tokens are zero.
"""
READS = ()

# Singular and plural words for a circumstance, condition, or use.
WORDS = {
    'case': -1.65, 'cases': -2.05,
    'scenario': -1.85, 'scenarios': -2.15,
    'situation': -2.0, 'situations': -2.7,
    'circumstance': -1.5, 'circumstances': -2.05,
    'condition': -0.5, 'conditions': -0.81,
    'occasion': -0.93, 'occasions': -1.07,
    'usage': -1.0, 'casing': -0.87,
    'instances': -0.54, 'exception': -0.33, 'exceptions': -0.36,
    'occurrence': -0.47, 'occurrences': -0.5,
}

# Translations and commonly tokenized stems of case/situation words.
TRANSLATIONS = {
    'cas': -0.62, 'caso': -1.6, 'casos': -1.6,
    'condiciones': -0.68, 'condizione': -0.6,
    'ситу': -2.0, 'ситуация': -1.8, 'ситуации': -1.77,
    'случае': -1.73, 'случаях': -2.04, 'случа': -1.8,
    'случая': -1.36, 'случай': -0.44,
    'situ': -0.53, 'situação': -1.13, 'situación': -1.13,
    'przypad': -2.62, 'tình': -0.8,
    'حالة': -2.18, 'حال': -1.12, 'กรณ': -1.86,
    '경우': -3.47, '경우에는': -1.7,
    '場合': -3.06, 'の場合': -2.93, '場合は': -2.43,
    '場合には': -1.93, 'ケース': -1.96,
    '状况': -2.12, '狀況': -1.95, '情形': -2.96,
    '的情形': -2.63, '案例': -0.97, '案件': -0.9,
    '场景': -0.77, '场合': -1.42, '路况': -1.5,
    # Related case/emotion characters, not semantic disambiguation.
    '情': -0.93, '的情': -1.0, '情人': -0.74, '案': -0.9,
}

DETERMINERS = {'the', 'this', 'any', 'our', 'my', 'your', 'such'}
QUANTIFIERS = {'some', 'most', 'many', 'in'}
LETTER_CASE = {'lower', 'upper', 'title', 'sentence'}


def case_strength(token, word, previous, two_back):
    value = WORDS[word]
    if token.startswith(' '):
        value -= 0.2
    elif token.startswith('\t'):
        value = -1.3 if word == 'case' else -1.8
    elif token.startswith('_'):
        value = -1.35 if word == 'case' else -2.2
    elif token.startswith('-'):
        value -= 0.25
    prior = previous.strip().lower()
    if previous.isspace() and '\n' not in previous:
        value += 0.65
    elif '\n' in previous:
        value += 0.25
    elif prior in DETERMINERS:
        value -= 0.4
    elif prior in QUANTIFIERS:
        value -= 0.35 if word == 'case' else 0.55
    elif prior == 'test':
        value += 0.3
    elif prior in LETTER_CASE:
        value += 0.4
    if prior == 'the' and two_back.strip().lower() == 'in':
        value -= 0.45
    if token.strip().isupper():
        value = -1.55
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0)
    _, previous, two_back, previous_pulse = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    plain = word.lstrip('_-.(')
    prior = previous.strip().lower()
    value = 0.0
    pulse = True

    if plain in {'case', 'cases'}:
        value = case_strength(token, plain, previous, two_back)
    elif plain in WORDS:
        value = WORDS[plain]
        if plain in {'scenario', 'scenarios', 'situation', 'situations', 'usage'}:
            if not token.startswith(' '):
                value *= 0.75
            if token.strip().istitle() and plain.startswith('situation'):
                value *= 0.55
        if plain == 'conditions' and token.strip().isupper():
            value = -1.3
    elif plain in {'testcase', 'testcases'}:
        value = -0.8
    elif word in TRANSLATIONS:
        value = TRANSLATIONS[word]
    elif word == 'hợp' and prior == 'trường':
        value = -2.1
    elif '情况' in word or '情況' in word:
        value = -4.3 if '情况' in word else -5.0
        if word.endswith('下'):
            value *= 0.78
        elif word not in {'情况', '的情况', '情況', '的情況', '等情况'}:
            value *= 0.85
    elif word in {'況', '况'}:
        value = -5.0 if prior.endswith('情') else (-3.0 if word == '况' else -2.1)
    elif word == '황':
        value = -2.5 if prior.endswith('상') else -1.5
    else:
        pulse = False

    if not pulse:
        if word == 'of' and previous_pulse < -0.4:
            value = 0.6 * previous_pulse
        elif word == 'where' and previous_pulse < -0.4:
            value = 0.3 * previous_pulse
        elif word == '下' and prior.endswith(('情况', '情況', '情形', '況', '况')):
            value = -2.0
    return (doc, token, previous, value if pulse else 0.0), float(value)

