"""Layer-0 MLP neuron 5387 (down_proj): a 'case / situation' detector.

It goes negative on the word "case" and close synonyms (situation, scenario,
circumstance, occasion) when they name a circumstance, as in "in the case of",
"in this case", "in any case", "in such situations", and on the same idea in other
languages (場合, 情况, 경우, caso, случае). The strength is about -2. It is weaker on
the programming keyword "case" (switch/case, about -1.5), on "condition(s)" (about
-0.7), and on "of" right after "case" in "in the case of" (about -1.4). Everywhere else
it predicts 0.
"""
READS = ()

SITUATION_WORDS = {"case", "cases", "situation", "situations", "scenario", "scenarios",
                   "circumstance", "circumstances", "occasion", "occasions"}
SITUATION_OTHER = {"場合", "情况", "情況", "況", "경우", "ケース", "狀況", "caso", "casos",
                   "случае", "ситуация", "fälle", "przypad", "案例", "案件", "情", "案"}
CONDITION_WORDS = {"condition", "conditions"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word in SITUATION_WORDS:
        # with a leading space it is prose ("in the case"); without, often code ("case 1:")
        return None, (-2.0 if token[:1] == " " else -1.5)
    if word in SITUATION_OTHER:
        return None, -1.6
    if word in CONDITION_WORDS:
        return None, -0.7
    if word == "of" and previous in ("case", "cases"):
        return None, -1.4
    return None, 0.0

