VOWEL_GAIN = {'e': 1.0, 'a': 0.53, 'o': 0.50, 'u': 0.29,
            'i': 0.24, 'y': 0.16, 'æ': 0.85,
            'е': 1.0, 'э': 1.0, 'а': 0.45, 'о': 0.40,
            'у': 0.30, 'и': 0.23, 'ы': 0.50, 'я': 0.55,
            'ю': 0.25, 'ε': 1.0, 'α': 0.53, 'ο': 0.50,
            'ω': 0.50, 'ι': 0.24, 'η': 0.24,
            'ا': 0.55, 'ی': 0.24, 'ي': 0.24}

# The vowel and initial consonant of kana come from their Unicode syllable names.
def kana_syllable(char):
    name = unicodedata.name(char, '')
    if char in 'っッ':  # A small tsu marks a consonant, not a vowel.
        return ''
