    if initial_kana.startswith('k'):
        katakana = unicodedata.name(token[0]).startswith('KATAKANA')
        scale = 1.6 if katakana else 0.45
        return gain * scale / len(token)
    first = plain(token[0])
    n = len(token)
    lower = token.lower()
    # A capitalized word is usually a new identifier, not a word fragment.
    if n > 1 and token[0].isupper() and any(c.islower() for c in token[1:]):
        return 0.0
    if first in 'ckqкцчκχكک':
        strength = (1.67 if n <= 2 else
                    1.29 if n <= 4 else 0.64 if n <= 7 else 0.46)
        if n == 1:
            strength = 1.75 if token == 'c' else 1.4
        if first in 'kкκكک':
            strength += 0.10
        if first == 'q':
            strength -= 0.29
        if lower.startswith('ck'):
            strength -= 0.42
        if lower.startswith('cz') or token[0].lower() == 'č':
            strength += 0.39
        if first == 'c' and lower[1:2] in ('e', 'i', 'y'):
            strength -= 0.50
        if lower.startswith('ki'):
            strength += 0.47
        if lower.startswith('cho'):
            strength -= 0.53
        if first in 'цчχ':
            strength -= 0.52
        if token[0].lower() in 'çć':
            strength -= 0.68
        if n > 1 and token.isupper():
            strength += 0.19
        # Unusual c-consonant pairs often function as abbreviation pieces.
        if n == 2 and first == 'c' and lower[1] in 'fgmpw':
            strength += 0.9
        # Long e-ending words are weaker than short syllable pieces.
        if vowel == 'e':
            letters = sum(c.isalpha() for c in previous)
            if letters == 1 and previous.strip().lower() == 'e':
                gain *= 1.25
            elif letters >= 5:
                gain *= 0.65
        return gain * max(0.0, strength)
    if first == 'g':
        return gain * (0.40 if n <= 4 else 0.12)
    if vowel in ('e', 'е', 'э'):
        second = plain(token[1]) if n > 1 else ''
        strength = 0.0
        if first in 'bvвб':
            strength = -0.65 if n == 1 or second in ('e', 'е') else -0.12
        elif first == 'u':
            strength = -0.85 if n == 1 or second in ('t', 'e', 'x') else -0.35
            if second in ('r', 'd', 'm'):
                strength = 0.0
        elif first in 'ai':
            strength = -0.23 if n == 1 else -0.10
            if second in ('b', 'n', 's') or (first == 'a' and second in ('t', 'e')):
                strength = -0.42
            if second == 'l' or (first == 'i' and second == 'r'):
                strength = 0.35
            if first == 'a' and second == 'b':
                strength = 0.45
        elif first in 'swy':
            strength = -0.55 if n == 1 else -0.25 if second in ('s', 't', 'n') else -0.06
        elif first in 'ptz':
            strength = 0.17
        # The eath rime and longer eur(e) endings have a stronger negative sign.
        if lower.startswith('ath'):
            strength = -1.1
        elif lower.startswith('ure'):
            strength = -0.7
        return strength * (1.0 if n <= 4 else 0.25)
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    value = transition(previous, token)
    return (document, token), float(value)

"""Approximate the dominant negative response to short 'ma' spelling pieces.

Training examples strongly respond to ma/mar/mat fragments and ma-like
characters across scripts. Longer words usually weaken this, with some
retained word families and weak common-word exceptions. The rules use length,
case, accents, and small named spelling groups, not token IDs. A few Chinese
machine/master/manufacturing words also get a weak fixed response.

State resets at document boundaries. Strong fragments get a document-initial
boost; m+a split spellings and immediately following continuations retain a
small response. Weaker unrelated responses are deliberately left out.
"""
import unicodedata

READS = ()

MA_CHARACTERS = {
    'マ': 4.4, 'ま': 3.2, '마': 4.95,
    '马': 4.15, '馬': 3.55, '玛': 4.0, '瑪': 3.55,
}
CODAS = {
    'r': 3.1, 't': 2.35, 's': 1.8, 'c': 1.9, 'l': 1.1,
    'k': 1.25, 'd': 0.75, 'g': 0.7, 'i': 0.55, 'u': 0.5,
    'n': 0.15, 'y': 0.15, 'p': 0.05, 'x': 0.03, 'm': 0.3,
}
# Lexical strength bands for longer ma beginnings, not arbitrary token IDs.
FAMILIES = (
    (1.8, ('master', 'marx', 'maturity')),
    (1.1, ('machin', 'marriag', 'mature', 'marathon', 'marie', 'marine')),
    (0.8, ('matri', 'matlab', 'mass', 'marit', 'matern', 'mathem')),
    (0.5, ('mark', 'march', 'marsh', 'mari', 'matt', 'magic', 'mal', 'mary')),
    (0.2, ('math', 'marg', 'matter', 'match', 'mask', 'mater')),
    (0.02, ('make', 'making', 'made', 'many', 'may', 'main')),
)


def roman(word, spaced):
    low = word.lower()
    i = low.find('ma')
    if i < 0 or i > 1 or (i and low[0] not in 'aeiou'):
        return 0.0
    if low == 'may':
        return 0.02
    if word == 'mA':  # milliampere is not the ma syllable
        return 0.55
    tail = low[i+2:]
    if not tail:
        value = 2.3 if word.islower() else (2.1 if word.isupper() else 2.5)
    else:
        value = CODAS.get(tail[0], 0.7)
        value *= (1.0, 0.5, 0.25)[min(len(tail)-1, 2)]
        if len(tail) > 3:
            value *= 0.6
    if i:
        value *= (1.0 if low[0] == 'a' and not tail else 0.5)
        if spaced:
            value *= 0.2 if low[0] == 'u' else 0.7
    elif len(low) > 3:
        for amplitude, roots in FAMILIES:
            if low.startswith(roots):
                value = amplitude
                break
        if low in ('matter', 'market', 'mask', 'match', 'machinery', 'mathematical'):
            value = 0.2
        if low == 'marine' or low == 'marin':
            value = 2.0
        if low.startswith('material'):
            value = 0.02
        if low == 'mathematic':
            value = 1.6
        if low in ('masters', 'mathematics'):
            value = 1.5 if low == 'masters' else 0.7
    elif spaced and word.islower() and tail[:1] in ('r', 't'):
        value *= 0.85
    if low.endswith(('matic', 'matics')) and len(low) <= 7:
        value = 1.15
    return value


def strength(s):
    word = s.strip().lstrip('_./-(')
    if word in MA_CHARACTERS:
        return MA_CHARACTERS[word]
    if len(word) <= 3 and word.startswith(('ま', 'マ')):
        if word.startswith(('また', 'ません')):
            return 0.0
        return 1.3 if word.startswith(('まり', 'まる', 'まっ')) else 0.65
    if len(word) == 2 and word.endswith(('ま', 'マ')):
        return 0.55 if word == 'さま' else 1.3
    if any(c in word for c in '马馬玛瑪'):
        return 1.15
    if word in set('吗嗎妈媽麻魔'):
        return 0.6
    if word in ('머', '말', '매'):
        return 0.95
    if word in ('มา', 'เม'):
        return 2.2 if word == 'มา' else 1.15
    if word.startswith('ما'):
        return 1.05 if len(word) <= 3 else 0.45
    if word in ('机器', '機器', '大师', '大師', '制造', '製造'):
        return 0.85
    if word in ('机', '機'):
        return 0.4
    if 'ма' in word.lower():
        latin = word.lower().translate(str.maketrans('марстлн', 'marstln'))
        return (0.8 if s[:1].isspace() else 0.6) * roman(latin, False)
    plain = ''.join(c for c in unicodedata.normalize('NFD', word)
                    if not unicodedata.combining(c))
    if word.lower() in ('más', 'mais'):
        return 0.2
    value = roman(plain, s[:1].isspace())
    return value * (0.4 if plain != word else 1.0)


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old, previous = ('', 0.0) if first else carry[1:]
    current, extra = strength(s), 0.0
    if first and current > 1.5 and not s[:1].isspace():
        extra = 1.0
    elif s and s[0].isalpha():
        if old.lower().endswith(('m', 'м', 'م')):
            if s.lower().startswith(('a', 'а', 'ا')):
                coda = s[1:2].lower()
                extra = min(0.75, max(0.4, 0.3 * CODAS.get(coda, 2.0)))
                if coda in ('n', 'н', 'ن', 'y', 'й', 'ي', 'p', 'x'):
                    extra = 0.1
                extra *= 0.9 ** max(0, len(s)-3)
                if s.lower().startswith(('achine', 'aster')):
                    extra = 1.7
                if s.isupper():
                    extra *= 1.4
            elif current > 1.5 and s.isascii():
                extra = 0.5
        elif current < 0.1:
            extra = previous * (0.14 if len(s) <= 2 else 0.07)
    if s in ('-m', '-M', '/m', '/M', '_m', '_M'):
        current = 0.55 if s == '-m' else 0.3
    return (doc, s, current), float(-current-extra)

programs.haiku:
"""Component layers.0.mlp.down_proj:5391: a "ma" detector.

Goes negative on tokens spelled with the syllable "ma" (ma, Ma, MA, mar, mat, mas, master,
ama ...) and on the same syllable written in CJK, kana, hangul or Cyrillic (马 馬 マ ま 마 ма).
Strongest for the bare fragments "mar"/"ma"/"mat", weaker for "mac", "mal", "mass", "mark".
Whole everyday words that begin with "ma" (make, many, may, man, map, main, match) stay at 0.
Other tokens are 0.
"""
import re

READS = ()

CJK_MA = {"马", "馬", "マ", "ま", "마"}
CYRILLIC_MA = {"ма", "мат", "мар", "мас"}
EVERYDAY = {"man", "may", "map", "make", "many", "main", "made", "match", "market", "major",
            "maybe", "mainly", "matter", "making", "manage", "more", "makes", "maximum"}


def _value(token):
    s = token.strip()
    t = s.lower()
    if s in CJK_MA:
        return -3.5
    if t in CYRILLIC_MA:
        return -1.7
    if t in EVERYDAY:
        return 0.0
    if t == "mar":
        return -3.0
    if t in ("ma", "mat", "mas"):
        return -2.3
    if re.match(r"^ma[rts]", t):
        return -1.2 if len(t) <= 4 else -0.5
    if t.startswith("ma"):
        return -0.15
    if "ma" in t:
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(_value(prefix.token_strings[-1]))

