programs.haiku:
"""Layer-0 MLP down-projection unit 5396: a weak, token-level feature.

It is negative on sentence-final periods (most negative in technical or math
text, where a '$', a backslash or "we" appears in the last 40 tokens), and
negative on argumentative or 'exposition' words such as "idea", "argument",
"see", "show", "method". It is mildly positive on a few concrete technical nouns,
and slightly negative on the first token of a document and on CJK characters.
Every other token predicts 0. The values are group means fitted on sample text.
"""

READS = ()

SENTENCE_END = {".", "$.", ".\n", ".\n\n", " ."}
ARGUMENT_WORDS = {
    " idea", " argument", " reasoning", " method", " approach", " style", " see",
    " show", " results", " examples", " example", " proof", " consider", " claim",
    " suppose",
}
TECHNICAL_NOUNS = {" storage", " mining", " gold", " trees", " coverage", " reduction",
                   " patent", " fluid", " solutions"}
MATH_MARKS = ("$", "\\", " we", "We")


def is_cjk(s):
    return any(0x2E80 < ord(c) < 0xA000 for c in s)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, -0.03
    window = "".join(prefix.token_strings[-40:])
    if token in SENTENCE_END:
        technical = any(m in window for m in MATH_MARKS)
        return None, (-0.02 if technical else -0.008)
    if token in ARGUMENT_WORDS:
        return None, -0.054
    if token in TECHNICAL_NOUNS:
        return None, 0.09
    if is_cjk(token):
        return None, -0.008
    return None, 0.0

programs.sol:
"""Approximate a negative signal for short 'ail' spellings.

Bare fragments and short rhyme-family words get the strongest response.
Most inflections, email, longer compounds and neighboring 'air'/'eil'/'ile'
spellings get smaller ones. A few adjacent-token rules cover split words
and 'failed to'; selected Chinese and Spanish translations are included.
Carry remembers only the previous spelling and resets between documents.
This is not a general classifier of failure meaning.
"""
import re

READS: tuple[str, ...] = ()
AIL_WORD = re.compile(
    r'(bail|fail|hail|jail|mail|nail|pail|rail|sail|tail|trail|wail)'
    r'(s|ed|ing|ers?|ors?|ures?)?'
)
AIL_FRAGMENT = re.compile(r'ail(s|ed|ing|er|le|les|y|able|ability|ure)?')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    letters = re.sub(r'^[^A-Za-z]+|[^A-Za-z]+$', '', token)
    word = letters.lower()
    strength = 0.0
    fragment = AIL_FRAGMENT.fullmatch(word)
    rhyme = AIL_WORD.fullmatch(word)
    if fragment:
        ending = fragment[1]
        strength = 6.3 if ending in {None, 's'} else 1.8
        if ending in {'ed', 'ing'}:
            strength = 4.8
        elif ending in {'er', 'le'}:
            strength = 3.4
        if token.startswith(' '):
            strength *= 0.7
    elif rhyme:
        stem, ending = rhyme.groups()
        strength = 5.2
        if stem == 'fail':
            strength = 4.7
        elif stem in {'rail', 'trail'}:
            strength = 4.2
        elif stem in {'jail', 'sail'}:
            strength = 4.7 if letters.istitle() else 2.8
        if ending == 's':
            strength *= 0.8
        elif ending in {'ed', 'ing'}:
            strength *= 0.65
        elif ending in {'er', 'ers', 'or', 'ors'}:
            strength = 1.5
        elif ending in {'ure', 'ures'}:
            strength = 2.8
        if token.startswith('-') and stem == 'mail':
            strength *= 0.55
    elif re.fullmatch(r'(e|g)mail(s|ed|ing)?', word):
        strength = 2.3
    elif word.startswith(('railway', 'railroad', 'retail', 'tailor')):
        strength = 1.3
    elif word == 'daily' or re.fullmatch(r'(air|hair|clair)(s|line|port)?s?', word):
        strength = 0.8
    elif word in {'eil', 'ceil', 'iled', 'iling', 'ile', 'iles', 'iler'}:
        strength = 0.7
    if letters.isupper():
        strength *= 0.8

    # Nearby pieces of the same word and the common 'failure to' construction.
    if word == 'to' and previous in {'fail', 'fails', 'failed', 'failing', 'failure'}:
        strength = 1.2
    elif word in {'ure', 'ures'} and previous == 'fail':
        strength = 1.8
    elif word in {'or', 'oring'} and previous == 'tail':
        strength = 2.8
    elif word in {'ail', 'ails'} and previous in {'sn', 'prev', 'av'}:
        strength = 4.6 if previous == 'sn' else 3.3
    if token.strip().lower() in {'尾', '邮', '郵', '失败', 'correo'}:
        strength = 2.4
    return (doc, word), -strength

programs.luna:
"""Predict negative values for 'ail', Cyrillic 'ай', and Korean date endings."""
READS = ()

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, '')
    if doc != old_doc:
        tail = ''

    piece = prefix.token_strings[-1]
    fragments = piece.split()
    fragment = fragments[-1].casefold() if fragments else ''
    previous = '' if any(ch.isspace() for ch in piece) else tail
    word = previous + fragment

    # Fire when this token adds the end of the spelling, not on later
    # subword pieces from the same word.
    def completed(spelling):
        start = word.rfind(spelling)
        return start >= 0 and start + len(spelling) > len(previous)

    if completed('ail'):
        value = -3.5
    elif completed('ай'):
        value = -0.7
    elif piece == '일' and tail and tail[-1].isdigit():
        value = -1.2
    else:
        value = 0.0

    full_word = (tail + piece).split()
    next_tail = full_word[-1][-32:] if full_word else ''
    if piece and piece[-1].isspace():
        next_tail = ''
    return (doc, next_tail), value

programs.haiku:
"""Chinese and English adverbs, modals and connectives that come before a verb or clause.

Layer-0 MLP output component that is strongly negative on words like 并 (also/and), 还 (still),
却 (but), 也 (also), 都 (all/already), 更 (more), 很 (very), 会 (will), 就 (then), and on English
"but", "even", "while", "without". Those words set up a predicate; the component writes a
negative push for them and is near zero elsewhere.

Prediction = a fixed negative value per word, in three strengths. A multi-character token counts
when every character is in the list (e.g. 还想, 可能会), with the average strength of its characters.
Punctuation is ignored, so "，并" counts as 并.
"""
import unicodedata

READS = ()

# Strength of each character when it stands alone or inside a token of only these characters.
TIER = {}
for ch in "并並还還却卻":                                  # strongest: 并 还 却 (also, still, but)
    TIER[ch] = -6.0
for ch in "也又都更很便再最仍尚亦曾竟且皆":                  # adverbs of degree, time, scope (also, very, again)
    TIER[ch] = -3.0
for ch in "会會能可要将將想应该必不没未别但而或就已正才只请請被真越均则則较較":
    TIER[ch] = -1.4                                       # modals, negation, connectives, a few adverbs

# Whole words, where the characters alone would mislead (e.g. 非 alone is ~0).
WORDS = {
    "甚至": -2.6, "居然": -3.0, "竟然": -3.4, "并不": -3.7, "并非": -3.0, "同时还": -4.6,
    "已经": -1.3, "可以": -0.9, "还是": -1.3, "是否": -2.6, "仍然": -2.7, "依然": -2.4,
    "尚未": -1.7, "没有": -1.1, "不要": -0.7, "但是": -0.9, "一直": -1.6, "非常": -1.6,
    "更加": -1.4, "更是": -2.2, "也在": -2.1, "能够": -0.9, "正在": -0.9,
}

# English words that set up a clause (" also" is ~0, so it is left out).
ENGLISH = {
    " but": -0.7, " But": -0.3, " even": -0.7, " Even": -0.7, " while": -0.7, " While": -0.7,
    " without": -0.7, " Without": -0.7, " yet": -0.7, " still": -0.5, " &&": -0.7,
    " cũng": -1.4, " đang": -1.3,
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s in ENGLISH:
        return carry, ENGLISH[s]
    core = "".join(c for c in s if not unicodedata.category(c).startswith(("P", "Z", "S")))
    if core in WORDS:
        return carry, WORDS[core]
    if core and all(c in TIER for c in core):
        return carry, sum(TIER[c] for c in core) / len(core)
    return carry, 0.0

