"""Approximate sparse negative responses to function and discourse words.

Sampled activations are strongest on a few connectives, degree words, and
Chinese grammatical particles. This compact lexical rule shrinks those spikes
and predicts zero for ordinary words.
"""

READS = ()

LINKERS = {
    "but", "while", "yet", "still", "even", "without",
    "但", "然而", "不过", "可是", "而", "却", "虽", "虽然",
}

DEGREE = {"更", "很", "真", "最", "都", "甚至"}
ADDITIVE = {"也", "并", "並", "还", "還", "又", "再", "就", "同时", "同時"}
MODAL = {"会", "要", "能", "可能", "可以", "需要", "被", "应", "該", "應"}
NEGATION = {"不", "没", "沒", "没有", "無", "无", "不能"}
ALTERNATIVES = {"或", "还是", "還是"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in LINKERS:
        value = -0.30 if ord(word[0]) < 128 else -0.40
    elif word in DEGREE:
