programs.sol:
"""Approximate a source/provenance response, with separate tab and boundary signals.

Physical isolation/extraction gives 'from' a stronger response than ordinary
origin language; motion, distance and change expressions give it less.
Source-process and laboratory-material tokens also get smaller positives. Most other
tokens are near zero. Coefficients are fitted approximations, not exact rules
for every word sense. State is just a short text tail, reset per document.
"""
import re

READS = ()
ISOLATION = set('isolate isolated isolates isolating isolation isol'.split())
EXTRACTION = set('extract extracted extracts extracting extraction'.split())
PREPARATION = set('prepare prepared preparation preparations preparing'.split())
ACQUISITION = set('obtain obtained obtaining'.split())
DERIVATION = set('derive derived derives deriving'.split())
FORMATION = set('made formed produced generated constructed'.split())
COLLECTION = set('collected taken selected separated samples sample'.split())
CHANGE = set('shift shifted shifting transition transitioning convert converted '
             'converting moving moved going'.split())
DISTANCE = set('away apart back distance distances aside'.split())
SOURCE_LEVELS = (
    (ISOLATION, 4.3), (EXTRACTION | PREPARATION, 3.35),
    (FORMATION | COLLECTION, 2.45), (ACQUISITION | DERIVATION, 2.12),
    (CHANGE, -0.55), (DISTANCE, -0.10),
)


def source_response(previous, default):
    for words, value in SOURCE_LEVELS:
        if previous in words:
            return value
    if previous == 'benefit':
        return -0.50
    if previous in {'data', 'information', 'files', 'images', 'evidence'}:
        return 1.15
    return default


