"""Approximate a spelling-level vowel-transition cue at token boundaries.

An unspaced o after u or a is strongly positive; e is weaker, and i/y are
usually negative. The two vowel identities, nearby consonants, fragment
length, spaces, accents, case, and vowel groups determine the response.
Cyrillic vowels are mapped to their Roman counterparts; ю, sharp-s/caron-s,
and the rounded glyph 0 have explicit adjustments. This is a local spelling
approximation, not a complete account of the component's lexical behavior.
"""
import unicodedata

READS = ()
VOWELS = 'aeiouy'
CYRILLIC = str.maketrans('аеёиоуыі', 'aeeiouyi')
# Previous last vowel -> next vowel, columns a e i o u y.
PAIRS = {
    'a': (0.12, 0.73, -0.24, 1.66, 0.12, -0.23),
    'e': (0.06, 0.06, -0.03, 0.40, -0.03, -0.03),
    'i': (0.02, 0.04, -0.07, 0.54, -0.05, -0.10),
    'o': (0.17, 0.13, 0.02, 0.15, 0.07, -0.02),
    'u': (0.66, 0.67, -0.45, 2.42, -0.13, -0.41),
    'y': (0.00, -0.01, -0.04, 0.22, -0.05, 0.02),
}
TAILS = {
    'a': (0.12, 0.05), 'e': (0.03, -0.02),
    'i': (0.17, 0.00), 'o': (-0.13, -0.28),
    'u': (0.16, 0.10), 'y': (0.01, -0.16),
}


def spelling(raw):
    s = unicodedata.normalize('NFKD', raw.lower()).translate(CYRILLIC)
    return ''.join(c for c in s if not unicodedata.combining(c)).strip()


def response(previous, current, raw):
    if not current:
        return 0.0
    original = raw.strip().lower()
    initial, gain = current[0], 1.0
    if original[:1] in {'j', 'ю', 'я', 'ї', 'ß', 'š'}:
        initial = 'y'
    if current == '0' and not raw[:1].isspace():
        initial, gain = 'o', 0.3
    if initial not in VOWELS:
        i = next((i for i, c in enumerate(current) if c in VOWELS), 99)
        if i not in (1, 2) or current[i] != 'o':
            return 0.0
        initial, gain = 'o', (0.25 if i == 1 else 0.07)
    previous = previous.replace('я', 'a').replace('ю', 'u')
    i = next((i for i in range(len(previous) - 1, -1, -1)
              if previous[i] in VOWELS), -1)
    distance = len(previous) - 1 - i
    if i < 0 or distance > 2:
        return 0.0
    vowel = previous[i]
    if original == 'ю' and distance == 0:
        return {'a': -1.0, 'u': -1.5, 'e': -0.4,
                'i': -0.4, 'o': -0.1, 'y': -0.2}[vowel]
    value = PAIRS[vowel][VOWELS.index(initial)] * gain
    if original[:1] in {'ß', 'š'}:
        value *= 1.3
    if distance:
        value *= TAILS[vowel][distance - 1]
        if distance == 1:
            value *= (2.5 if previous[-1] in 'szx' else
                      1.6 if previous[-1] in 'mnlr' else 1.0)
    value *= (0.85 if len(previous) > 2 else 1.0)
    value *= (0.56 if len(previous) > 4 else 1.0)
    if previous.endswith('qu'):
        value *= 0.25
    if initial == 'a':
        value *= (1.6 if current[-1] in 'mn' else
                  0.3 if current[-1] in VOWELS + 'szx' else 0.6)
    value *= 0.78 if len(current) > 4 else 1.0
    if raw[:1].isspace():
        value *= 0.11
    if len(raw.strip()) > 1 and raw.strip().istitle():
        value *= 0.4
    accented = any(unicodedata.combining(c) for c in
                   unicodedata.normalize('NFKD', raw))
    if accented and original[:1] not in {'š', 'ї'}:
        value *= 0.5
    # Count vowel groups, except a potentially silent final e/es.
    sound = current[:-2] if current.endswith('es') else (
        current[:-1] if current.endswith('e') else current)
    groups = sum(c in VOWELS and (i == 0 or sound[i - 1] not in VOWELS)
                 for i, c in enumerate(sound))
    return value * 0.8 ** max(0, groups - 1)


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    current = spelling(raw)
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    return (doc, current), float(response(previous, current, raw))

