"""Detect quotation delimiters, dominated by backticks around inline code.

Single backticks give a large negative pulse; doubled/fenced backticks and
prose quotation marks give smaller ones. Nearby backticks damp the pulse:
a decaying count of backtick-containing tokens records repetition, while
a gap records the last occurrence.
Whitespace, attached punctuation, and line endings distinguish delimiters.
Ordinary text is approximated by zero. State resets between documents.
"""
import math

READS = ()


def backtick_pulse(token):
    bare = token.lstrip(" ")
    count = bare.count("`")
    spaced = token.startswith(" ")
    if count >= 3:
        return -1.6
    if count == 2:
        return -2.7 if bare.strip("`") == "" else -0.95
    if "\n" in token:
        return -3.85 if spaced else -1.95
    if bare == "`":
        return -5.5 if spaced else -4.45
    if bare.endswith("`"):
        if bare.startswith("()"):
            return -3.1
        return -4.9 if spaced else -4.2
    if bare.startswith("`") and bare[1:] in {",", ".", ":", ")", ";"}:
        return -2.35
    return -3.85 if spaced else -4.05


def prose_quote(token, previous):
    bare = token.strip()
    if bare in {"《", "「", "『"}:
        return -0.85
    if bare.endswith(("“", "‘", "„")):
        return -0.6 if token != "“" else -0.45
    if bare == "«":
        return -0.47 if token.startswith(" ") else -0.28
    if token in {' "', " '"}:
        if '"' in previous or "'" in previous or previous.isspace():
            return 0.06 if token == ' "' else -0.03
        if previous.strip().isalpha():
            return -0.45
        if any(c in previous for c in "=+<>()"):
            return -0.03 if token == ' "' else -0.15
        return -0.25
    if bare.endswith('\\"'):
        return -0.3 if bare == '\\"' else -0.46
    if bare in {'{"', "{'", '["', "['"}:
        return -0.35 if not token.startswith(" ") else -0.26
    if bare in {'("', "('"}:
        return -0.25 if token.startswith(" ") else -0.1
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        recent, gap, previous = 0.0, 512, ""
    else:
        _, recent, gap, previous = carry
    token = prefix.token_strings[-1]
    if "`" in token:
        repetition = 0.42 * math.log1p(recent) + 3.3 / (1.0 + gap)
        value = backtick_pulse(token) + repetition
        recent += 1.0
        gap = 0
    else:
        value = prose_quote(token, previous)
    recent *= 0.992218  # exponential decay over 128 tokens
    gap = min(512, gap + 1)
    return (document, recent, gap, token), float(value)

