def is_word(tok):
    """A token that is a plain English word, with or without its leading space."""
    return tok.lstrip(" ").isalpha()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if "``" in tok:
        return None, -0.6
    if "`" in tok:
        if tok.startswith("`") and len(tok) > 1:
            return None, -1.0
        recent = prefix.token_strings[-LOOKBACK - 1:-1]
        if not any("`" in s for s in recent):  # first backtick after a stretch of prose
            return None, -5.0 if tok == " `" else -4.0
        if tok == " `" and is_word(prev):
            return None, -4.5
        return None, -2.7
    if tok.strip() in CURLY_OPEN:
        return None, CURLY_OPEN[tok.strip()]
    return None, STRAIGHT.get(tok, 0.0)

programs.sol:
"""Local English phrases linking an outcome to its cause or source.

The largest response is at 'of' in 'result of' and at 'from' in
'resulting from'. Production verbs strengthen 'by'; source and temporal
words have smaller defaults. Type, separation, and arithmetic phrases
suppress the response. An 80-character tail tracks the previous word,
resetting whenever the document changes. Definite outcome noun phrases
are stronger than bare result words. Unmatched tokens predict zero.
"""
import re

READS = ()


def words(text):
    return set(text.split())

OUTCOMES = words('result results outcome outcomes output outputs')
CREATION = words('produced formed generated created')
DERIVATION = words(
    'obtained derived extracted calculated determined inferred learned'
)
EMERGENCE = words('arise arises arising emerge emerges emerged emerging')
CONSEQUENCES = words(
    'consequence consequences aftermath remnants remainder findings'
)
PARTS = words('part portion rest contents details snippet combination sequence')
MEASURES = words('value values cost ratio probability volume loss derivative')
TYPES = words('types varieties range source sources origin origins')
SEPARATION = words('separate separated distinct differ differs excluded')


def phrase(word, prev):
    if word == 'of':
        if prev in OUTCOMES:
            return 6.4 if prev in {'result', 'outcome'} else 5.4
        if prev in CONSEQUENCES:
            return 3.1
        if prev in {'product', 'products'}:
            return 2.4
        if prev in {'effect', 'effects', 'impact', 'sum', 'end', 'out',
                    'goal', 'aim', 'purpose', 'objective', 'summary'}:
            return 1.45
        if prev in PARTS:
            return 0.85
        if prev in MEASURES:
            return 0.65
        if prev in TYPES or prev in {'lots', 'plenty', 'thousands', 'millions'}:
            return -0.6
        return 0.06
    if word == 'from':
        if prev in {'resulting', 'resulted'}:
            return 7.0
        if prev in OUTCOMES:
            return 5.3
        if prev in CREATION or prev in EMERGENCE:
            return 3.9
        if prev == 'made':
            return 3.3
        if prev in DERIVATION:
            return 2.5
        if prev in {'different', 'starting', 'subtract', 'subtracted'}:
            return -1.2
        if prev in SEPARATION:
            return -0.5
        if prev in {'range', 'ranging', 'distance', 'apart'}:
            return -0.15
        if prev in {'removed', 'taken', 'selected', 'away', 'graduated'}:
            return 0.4
        return 0.9
    if word == 'by':
        if prev in CREATION:
            return 2.8
        if prev in {'caused', 'induced', 'obtained'}:
            return 2.2
        if prev in {'calculated', 'determined', 'made', 'found', 'built', 'released'}:
            return 1.65
        if prev in {'shown', 'reported', 'published', 'recorded',
                    'collected', 'affected'}:
            return 1.1
        if prev in {'divisible', 'divide', 'dividing'}:
            return -1.2
        if prev in {'divided', 'multiplied', 'multiply', 'multiplying'}:
            return -0.55
        if prev.endswith('ed') or prev in {'given', 'done', 'shown'}:
            return 0.5
        return 0.1
    if word == 'when':
        return 0.28 if prev in {'only', 'even'} else 0.57
    if word == 'after':
        return 0.2 if prev in {'named', 'sought'} else 0.8
    if word == 'to':
        return 0.56 if prev == 'need' else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry and carry[0] == doc else ''
    match = re.search(r'(?:([A-Za-z]+)\s+)?([A-Za-z]+)\s*$', tail)
    prev = match.group(2).lower() if match else ''
    before = (match.group(1) or '').lower() if match else ''
    token = prefix.token_strings[-1]
    bare = token.strip().strip('._-()')
    word = bare.lower()
    value = phrase(word, prev)
    if word == 'of' and prev == 'result':
        if before == 'the':
            value = 6.8
        elif before in {'a', 'an'}:
            value = 5.4
    if word in OUTCOMES and token.startswith(' ') and bare.islower():
        ordinary, definite = {
            'result': (0.15, 1.05), 'results': (0.15, 0.75),
            'outcome': (0.8, 1.7), 'outcomes': (0.65, 1.2),
            'output': (0.13, 0.55), 'outputs': (0.15, 0.55),
        }[word]
        value = definite if prev == 'the' else ordinary
        if word == 'result' and prev in {'a', 'an'}:
            value = 0.7
    elif word == 'resulting':
        value = 0.45
    elif word in {'consequence', 'consequences'}:
        value = 0.65
    elif word == 'of' and not token.startswith((' ', '-')):
        value = 0.06
    elif word == 'by' and (not token.startswith(' ') or not bare.islower()):
        value = 0.0
    elif bare[:1].isupper() and word in {'from', 'when', 'after'}:
        value = {'from': 0.82, 'when': 0.48, 'after': 0.65}[word]
    return (doc, (tail + token)[-80:]), float(value)

programs.haiku:
"""Source/agent/time prepositions in a sentence (a rough, hand-made detector).

'from' fires most, then 'after', 'by' and 'when'. 'by' is strongest right after a
past participle ("released by", "synthesized by", "influenced by").
'of' is weak in general, but fires when it follows a noun of result, part or
origin ("result of", "part of", "out of", "son of"). Every other token is 0.
"""
READS = ()
WEIGHTS = {"from": 1.0, "after": 0.7, "when": 0.4}
OF_AFTER = {"result", "product", "rest", "out", "part", "report", "snippet",
            "son", "coast", "value", "equivalent", "course", "stage", "relief",
            "explanation", "set", "couple", "data"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "of":
        return carry, 0.8 if prev in OF_AFTER else 0.15
    if word == "by":
        return carry, 1.0 if prev.endswith("ed") else 0.4
    return carry, WEIGHTS.get(word, 0.0)

programs.sol:
"""Approximate the component's mainly lexical response to 'given'.

Predict a large negative value for 'given', especially capitalized or after
clause/field punctuation, and less after auxiliary verbs or articles. Echo
some of it on the next determiner or 'that'; use small positive values on
following 'by', 'in', 'to', and 'as'. Related giving/premise words have
smaller responses, including a few Chinese, German, and Russian forms.
The spelling fragment 'iven' also receives a negative value. Everything
else is zero. Remember the previous token and its predicted given-strength,
resetting at document boundaries.
These are empirical lexical/syntactic rules, not a semantic parser.
"""
import re

READS = ()
BE = {'am', 'is', 'are', 'was', 'were', 'be', 'being', 'been'}
HAVE = {'have', 'has', 'had'}
SMALL_RESPONSES = {
    'give': -0.26, 'gave': -0.24, 'giving': -0.32,
    'provided': -0.42, 'assuming': -0.44,
    'considering': -0.94, 'especially': -0.80,
    'regardless': -0.29, 'irrespective': -0.40,
    'follow': -0.28,
    # Chinese expressions meaning 'given', 'based on', or 'according to'.
    '鉴于': -2.5, '既然': -1.4, '基于': -1.25, '根据': -0.57,
    # Forms of the verb 'give' in Chinese and German.
    '给': -0.60, '給': -0.26, 'geben': -1.1,
    # Russian inflections of 'given' (dannyi).
    'дан': -0.8, 'данный': -0.6, 'данной': -1.1, 'данном': -0.75,
}
FOLLOWING_GIVEN = {
    'the': 0.29, 'that': 0.18, 'a': 0.23, 'an': 0.20,
    'its': 0.14, 'this': 0.14,
}
GIVEN_PREPOSITIONS = {'by': 0.33, 'in': 0.23, 'to': 0.13, 'as': 0.15}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_given = '', None
    else:
        _, previous, previous_given = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    last_word = re.search(r'([A-Za-z]+)$', previous.strip())
    prev_word = last_word.group(1).lower() if last_word else ''
    value = 0.0
    given = None
    if lower == 'given':
        if word[0].isupper():
            value = -6.5 if token.startswith(' ') else -6.9
        elif not token.startswith(' '):
            value = -4.7
        elif prev_word in HAVE:
            value = -1.25
        elif prev_word == 'been':
            value = -1.7
        elif prev_word in {'am', 'is', 'are'}:
            value = -2.55
        elif prev_word in {'was', 'were'}:
            value = -2.05
        elif prev_word == 'be':
            value = -2.25
        elif prev_word == 'being':
            value = -2.7
        elif prev_word == 'the':
            value = -3.55
        elif prev_word in {'a', 'an'}:
            value = -4.1
        elif previous.rstrip().endswith(','):
            value = -6.2
        elif re.search(r'[;:|]|—|->', previous):
            value = -5.55
        elif prev_word == 'but':
            value = -6.1
        else:
            value = -4.4
        given = value
    elif previous_given is not None:
        if lower in FOLLOWING_GIVEN:
            value = FOLLOWING_GIVEN[lower] * previous_given
        elif lower in GIVEN_PREPOSITIONS:
            value = GIVEN_PREPOSITIONS[lower]
    elif lower == 'following':
        value = 0.04 if prev_word == 'the' else -0.65
        if word[0].isupper():
            value = -0.9
    elif lower == 'based':
        value = 0.06 if prev_word in BE else -0.33
        if word[0].isupper():
            value = -0.6 if token.startswith(' ') else -0.9
    elif lower in SMALL_RESPONSES:
        value = SMALL_RESPONSES[lower]
        if lower == 'considering':
            if prev_word in BE or prev_word in {'before', 'after', 'without'}:
                value = -0.6
            elif (previous.rstrip().endswith(',')
                  or prev_word in {'but', 'especially'}):
                value = -1.5
    elif lower == 'iven':
        value = -5.8 if previous.lower().endswith('g') else -2.4
    return (doc, token, given), float(value)

