programs.sol:
"""An o-to-continuation signal at token boundaries.

Short, unspaced letter fragments after o give a positive response; longer
fragments rapidly weaken it. Repeating o, or forming ou, suppresses it.
Cyrillic/Greek o and accented Latin o are included. Greek o completed
from byte fragments is recognized separately. Hyphens and apostrophes
receive a moderate signal, and null separators are ignored.
"""
import unicodedata

READS = ()


def o_strength(text):
    if not text:
        return 0.0
    char = text[-1]
    plain = unicodedata.normalize("NFD", char)[0]
    if char in "oO":
        return 1.0
    if char in "оО":
        return 0.85
    if plain in "οΟ":
        return 2.0
    if plain in "ωΩ":
        return 0.4
    if plain in "oO":
        return 0.45
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, strength = (
        carry[1:] if carry and carry[0] == doc else ("", 0.0)
    )
    value = 0.0
    if strength and token and not token[0].isspace():
        first = unicodedata.normalize("NFD", token[0])[0]
        if token[0].isalpha() and not ("\u3400" <= token[0] <= "\u9fff"):
            if len(previous.strip()) > 4:
                strength *= 0.75
            if any(o_strength(c) for c in token):
                value = -0.04
            else:
                value = strength * 1.4 * 0.42 ** (len(token) - 1)
                if first in "uUυΥ":
                    value *= 0.28
                if len(token) > 2 and token[0].isupper():
                    value *= 0.35
        elif token.startswith(("-", "'", "’")):
            value = strength * 0.65
    new_strength = o_strength(token)
    if "�" in token and carry and carry[0] == doc:
        # Decode only when a token cuts a Unicode character into byte pieces.
        char = prefix.text_prefixes[-1][-1:]
        base = unicodedata.normalize("NFD", char)[:1]
        if token.strip() == "�" and base in ("ο", "Ο"):
            value = 1.9 if char in "οΟ" else 1.2
            new_strength = 0.6
    if token == "\x00":
        token, new_strength = previous, strength
    return (doc, token, new_strength), float(value)

programs.luna:
"""Predict a sparse activation from Unicode spelling, not word meaning.

It assigns fixed offsets by script, tracks consecutive Greek and Katakana
tokens (resetting at document changes), and gives U+FFFD and historic long-s
their own offsets.  Most activations remain unexplained by this heuristic.
"""
import unicodedata

READS = ()


def script(char):
    name = unicodedata.name(char, "")
    for label in (
        "LATIN", "GREEK", "CYRILLIC", "HIRAGANA", "KATAKANA",
        "HANGUL", "CJK", "ARABIC", "HEBREW", "DEVANAGARI", "THAI",
    ):
        if label in name:
            return label
    return "OTHER"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    kinds = {script(char) for char in token if char.isalpha()}
    if "GREEK" in kinds:
        kind = "GREEK"
    elif "KATAKANA" in kinds:
        kind = "KATAKANA"
    elif "HIRAGANA" in kinds:
        kind = "HIRAGANA"
    elif "THAI" in kinds:
        kind = "THAI"
    elif "CYRILLIC" in kinds:
        kind = "CYRILLIC"
    elif "ARABIC" in kinds:
        kind = "ARABIC"
    elif "OTHER" in kinds:
        kind = "OTHER"
    elif "LATIN" in kinds:
        kind = "LATIN"
    else:
        kind = "NONE"

    doc = int(prefix.document_ids[-1])
    if carry and carry[0] == doc and carry[1] == kind and kind != "NONE":
        run = min(carry[2] + 1, 4)
    else:
        run = 1 if kind != "NONE" else 0

    if "\ufffd" in token:
        value = 0.057
    elif "ſ" in token:
        value = 0.37
    elif kind == "GREEK":
        value = {1: 0.029, 2: 0.133, 3: 0.243, 4: 0.164}[run]
    elif kind == "KATAKANA":
        value = {1: -0.016, 2: 0.090, 3: 0.294, 4: 0.100}[run]
    elif kind == "HIRAGANA":
        value = 0.014
    elif kind == "THAI":
        value = -0.076
    elif kind == "CYRILLIC":
        value = 0.009
    elif kind == "ARABIC":
        value = -0.008
    elif kind == "OTHER":
        value = -0.064
    else:
        value = 0.003
    return (doc, kind, run), value

programs.sol:
"""Approximate a chat-boundary and Korean-script signal.

Turn endings and tool-call tags are positive; thought tags are negative.
Hangul is positive, especially a space-prefixed, one-syllable token. Korean
appearing after 16 tokens without recognized Hangul gets an extra boost.
Document starts are treated separately. Completed Hangul byte fragments get
a small pulse; recent Hangul identifies likely unfinished Korean word starts.
Other tokens receive zero, leaving lexical variations unmodeled.
"""
READS = ()

BOUNDARIES = {
    '<tool_call>': 2.51,
    '</tool_call>': 2.31,
    '<tool_response>': 0.145,
    '</tool_response>': 0.145,
    '<think>': -0.40,
    '</think>': -1.29,
}


def hangul(char):
    return '\uac00' <= char <= '\ud7a3'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    new_doc = carry is None or carry[0] != doc
    if new_doc:
        previous, recent_korean = '', 0
    else:
        _, previous, recent_korean = carry

    count = sum(hangul(c) for c in token)
    completed = False
    if '\ufffd' in token and not new_doc:
        completed = any(hangul(c) for c in prefix.text_prefixes[-1][-1:])

    if token == '<|im_end|>':
        value = 3.28
        if previous == '</tool_call>':
            value = 3.49
        elif previous == '</tool_response>':
            value = 3.08
    elif token in BOUNDARIES:
        value = BOUNDARIES[token]
    elif count:
        if token.startswith(' ') and count == 1:
            value = 3.65
        elif token.startswith(' ') and count == 2:
            value = 2.15
        elif count >= 3:
            value = 1.60
        else:
            value = 1.85
        if new_doc:
            value = 2.2 if token.startswith(' ') and count == 1 else 1.6
        elif not recent_korean:
            value += 1.5
    elif token == ' \ufffd' and recent_korean:
        value = 4.40
    elif completed:
        value = 1.0
    else:
        value = 0.0

    recent_korean = 16 if count or completed else max(0, recent_korean - 1)
    return (doc, token, recent_korean), value

programs.haiku:
"""Korean-text detector for layers.0.mlp.down_proj:5420.

This component is a token-identity feature for Korean (Hangul) text. It is silent on
almost all tokens. It switches on:
  * Hangul syllable tokens: strongly (about 3.2) when the token starts a word, i.e. has a
    leading space (" 기", " 정"), and moderately (about 1.9) when it continues a word
    (the particles 을, 이, 에, 의, 를 and so on);
  * byte fragments of Korean characters, which decode alone to U+FFFD: about 4 for
    " �" (space plus fragment) and about 1 for a bare "�", but only while the recent
    text (last 30 tokens of the document) contained Hangul. Outside Korean text they are 0;
  * the chat/tool markers <|im_end|> (3.3), <tool_call> (2.5), </tool_call> (2.3), and a
    weak negative value on </think> (-1.3).
Everything else is 0.
"""

SPECIAL = {"<|im_end|>": 3.3, "<tool_call>": 2.5, "</tool_call>": 2.3, "</think>": -1.3}
KOREAN_WINDOW = 30  # tokens of Korean context that keep the fragment rule on


def is_hangul(s):
    return any("가" <= c <= "힣" or "ᄀ" <= c <= "ᇿ" for c in s)


READS = ()


def step(carry, prefix, upstream):
    # carry: how many more tokens the text still counts as Korean context.
    korean = carry or 0
    docs = prefix.document_ids
    if len(docs) > 1 and docs[-1] != docs[-2]:
        korean = 0  # a new document starts: forget the earlier text
    s = prefix.token_strings[-1]
    if s in SPECIAL:
        value = SPECIAL[s]
    elif is_hangul(s):
        value = 3.2 if s.startswith(" ") else 1.9
        korean = KOREAN_WINDOW
    elif "�" in s and korean > 0:
        value = 4.0 if s.startswith(" ") else 1.0
    else:
        value = 0.0
    if korean > 0 and not is_hangul(s):
        korean -= 1
    return korean, value

