"""Approximate a recurring trigger around attention and careful handling.

The recognized words describe noticing, considering, avoiding, or handling an
issue.  The program uses only the current token (plus a few fixed phrases), so
it misses equivalent wording and the component's context-dependent strength.
"""
READS = ()

# Plain-language ways to attend to an issue or take care in dealing with it.
ATTENDING = {
    "note", "notice", "consider", "avoid", "handle", "process",
    "emphasize", "focus", "attention", "care", "track", "deal",
    "treat", "ensure", "effort", "proper", "cautious", "deliberate",
    "look", "eye", "forget", "关注", "處理", "忘", "不用担心",
    "きちんと",
}


def word_forms(token):
    word = token.strip().strip(".,!?;:()[]{}\"'`*_#<>/\\").casefold()
    forms = {word}
    if word.endswith("ing") and len(word) > 5:
        forms.update((word[:-3], word[:-3] + "e"))
    if word.endswith("ed") and len(word) > 4:
        forms.update((word[:-2], word[:-2] + "e"))
    for suffix in ("es", "s"):
        if word.endswith(suffix) and len(word) > len(suffix) + 3:
            forms.add(word[:-len(suffix)])
            break
    return word, forms


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    word, forms = word_forms(prefix.token_strings[-1])

    value = 0.0
    if forms & ATTENDING:
        value = 0.6
    elif word in {"on", "with"}:
        previous = " ".join(recent[-7:])
        if word == "on" and "focus" in previous:
            value = 0.6
        if word == "with" and "deal" in previous:
            value = 0.6

    return (doc, (recent + (word,))[-8:]), float(value)

"""Conservative estimate of degree-modified descriptive words."""
READS = ()

DEGREE_WORDS = {
    "more", "most", "very", "so", "too", "less", "least",
    "quite", "rather", "highly", "especially", "extra",
    "better", "greater", "poorly", "even",
    "très", "peu", "plus", "più", "más", "очень",
    "更加", "更", "最", "非常",
}
ADJECTIVE_ENDINGS = (
    "able", "ible", "ive", "ous", "ful", "less",
    "ant", "ent", "al", "ic", "ar", "ing", "ed",
    "ly", "y",
)

def clean(s):
    return s.strip().strip(".,!?;:()[]{}\"'“”‘’").lower()

def is_cjk(s):
    return any("\u3400" <= c <= "\u9fff" for c in s)

def step(carry, prefix, upstream):
    i = prefix.position
    token = prefix.token_strings[-1]
    current = clean(token)
    value = 0.0

    # A comparative word and the descriptive word following it get a small vote.
    if current in {"more", "most"}:
        value = 0.55
    elif i and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = clean(prefix.token_strings[-2])
        descriptive = (
            is_cjk(current)
            or current.endswith(ADJECTIVE_ENDINGS)
            or current in {"equal", "popular", "little", "famous"}
        )
        if previous in DEGREE_WORDS and descriptive:
            value = 0.55 if current == "little" and previous == "very" else -1.0

    return None, value

