CODE_EXT = set(
    ".go .ts .tsx .js .jsx .java .rs .sh .h .hpp .cpp .cc .c .cs .php .pl .rb .kt .swift "
    ".css .scala .lua .yaml .yml .jar .dll .vue .cfg .ini .toml .properties .gradle .exe .so".split()
)
DOC_EXT = set(
    ".md .txt .pdf .json .xml .html .htm .csv .log .owl .rdf .png .jpg .gif .zip .iso".split()
)
DOMAIN_SUFFIX = set(
    ".com .org .edu .gov .net .de .uk .au .cn .ru .ua .kr .in .co .us .ac .io .ke .es .be "
    ".fi .nl .fr .it .jp .br .info .dev".split()
)
# Less common or ambiguous suffixes (.git, .test, .spec, .length, ...): a weak signal.
WEAK_EXT = set(".git .test .spec .example .length .id .m .g .p .st .k .f .d .r .ch".split())

# Typical activation for each group.
VALUE = {"python": -6.4, "code": -3.8, "doc": -2.3, "domain": -2.6, "weak": -0.3}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in PYTHON_EXT:
