READS = ()

# An item at a camel-case word boundary, not 'itemap' or 'omitempty'.
ITEM_PART = re.compile(r'(^item(?=[A-Z]|id$)|Item(?=[A-Z]|s$|$))')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._([<\"\'/$-')
    lower = word.lower()
    value = 0.0
    if lower in {'item', 'items'}:
        value = -5.3 if lower == 'item' else -4.45
        if token.lstrip().startswith(('(', '<')):
            value += 1.2 if lower == 'item' else 0.6
        elif word == 'Item' and not token.startswith(' '):
            value -= 0.6
    elif ITEM_PART.search(word) or lower in {'getitem', 'setitem'}:
        value = -3.2 * min(1.0, 8.0 / len(word))
        if word in {'getItem', 'setItem'}:
            value = -5.3 if token.startswith(' ') else -4.15
        elif lower in {'getitem', 'setitem'}:
            value = -2.3
        elif lower in {'getitems', 'setitems'}:
            value = -2.7
        elif 'menu' in lower or 'stack' in lower:
            value *= 0.4
        elif word == 'toItem':
            value = -1.8
    elif lower in {'itemprop', 'iteritems'}:
        value = -1.7
    elif lower in {'article', 'articles'}:
        value = -0.9 if word == 'article' and token.startswith(' ') else -0.6
    elif lower in {'inventory', 'merchandise'}:
        value = -1.0
    elif lower in {'iter', 'iterator', 'iterable', 'itertools'}:
        value = -0.2 if word == 'Iterator' else -0.6
    elif lower in {'goods', 'piece', 'pieces', 'commodity', 'commodities', 'obj'}:
