    elif lower in {'artikel', 'articulo', 'artículo'}:
        value = -0.7
    elif lower in {'товар', 'товары', 'товаров'}:
        value = -1.2
    elif lower == 'itens':
        value = -2.4
    elif any(s in token for s in ('商品', '物品', 'アイテム')):
        value = -2.9
    elif word == '项':
        value = -1.7
    elif word in {'項', '項目', '件', '一件', '是一件', '这件', '品'}:
        value = -1.1
    elif word.endswith('项') and all(c in '一二三四五六七八九十两各每这那该的'
                                       for c in word[:-1]):
        value = -1.3
    elif word in {'用品', '药品', '极品', '库存', '实物', '宝贝'}:
        value = -0.75
    elif word in {'条', '项目', '材料'}:
