programs.sol:
"""Lexical Python cues and document separators.

Recognize Python names/files, imports, booleans, errors, testing vocabulary,
magic double-underscore names and docstrings. Selected Python methods and
installed-package paths also respond. Most unmatched vocabulary gets zero.
A bounded text tail recognizes split library names and distinguishes testing
words in nearby Python text. In such text, the pytest-style separator '::'
gets a negative value; 'self' has a separate signed rule. Document changes
reset the tail and token count. Levels approximate training group averages;
no token IDs or model computations are used.
"""
import builtins
import re

READS = ()
PYTHON_LIBRARIES = set('''
    pytest unittest django sqlalchemy flask werkzeug setuptools pygame
    pydantic attrs boto botocore argparse pathlib tempfile shutil itertools
    functools tkinter urllib
'''.split())
INTROSPECTION = {'getattr', 'setattr', 'hasattr', 'isinstance', 'issubclass'}
PYTHON_ERRORS = {name for name in dir(builtins) if name.endswith('Error')}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, tail = 0, ''
    else:
        position, tail = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    name = word.lstrip('.(/_-="\'')
    low = name.lower()
    value = 0.0
    if token == '<|endoftext|>':
        value = (0.394 if position == 0 else 0.70 if position < 4 else
                 0.79 if position < 16 else 0.82 if position < 64 else 0.88)
    elif word == '.py':
        value = 1.0
    elif low in {'python', 'python3', 'cpython', 'ipython', 'pypy'}:
        value = 1.30 if word.startswith(('/', '.')) else 0.73
    elif name in {'py', 'Py'}:
        value = 0.35
    elif '__' in word and '___' not in word:
        if not word.endswith(('/', ':')) and '\n' not in token:
            value = (0.81 if word.startswith('/') else
                     0.28 if token == '__' else 0.44)
    elif name in {'True', 'False'}:
        value = 0.55
    elif name in {'true', 'false'}:
        value = 0.19
    elif name in {'import', 'Import', 'imports'}:
        value = (0.53 if token.startswith(' ') else
                 0.21 if token.startswith('\t') else 0.32)
    elif name in PYTHON_ERRORS or name in INTROSPECTION:
        value = 0.85
    elif low in {'pytest', 'unittest'}:
        value = 0.95
    elif low in PYTHON_LIBRARIES:
        value = 1.40 if low in {'django', 'sqlalchemy'} else 0.65
    elif name in {'kwargs', 'cls', 'TestCase', 'TestClass'}:
        value = 0.80
    elif name in {'Error', 'Exception', 'Warning'}:
        value = 0.25
    elif name in {'staticmethod', 'classmethod', 'cached_property'}:
        value = 0.92
    elif '"""' in token or "'''" in token:
        value = 0.40
    elif name in {'test', 'tests', 'Test', 'testing'}:
        python_seen = bool(re.search(r'python|django|pytest|\.py\b', tail, re.I))
        value = (0.30 if word.startswith('/') else
                 0.02 if token[0].isspace() or word.startswith('_') else
                 0.27 if name == 'tests' else 0.13) + 0.23 * python_seen
    elif word == '::':
        python_seen = bool(re.search(r'python|django|pytest|\.py\b', tail, re.I))
        value = -0.29 if python_seen else 0.0
    elif name == 'self':
        value = 0.10 if '(' in word else -0.13
    elif word.startswith('.') and name in {'dumps', 'loads'}:
        value = 0.95
    elif word.startswith('.') and name in {'join', 'startswith', 'endswith',
                                          'rstrip', 'getvalue', 'environ',
                                          'stderr', 'stdout', 'makedirs'}:
        value = 0.55
    elif word == '-packages' and tail.endswith(('site', 'dist')):
        value = 1.05
    if value == 0.0 and token and token[-1].isalpha():
        match = re.search(r'([A-Za-z][A-Za-z0-9_]*)$', tail + token)
        completed = match.group(1).lower().split('_')[-1] if match else ''
        if completed in PYTHON_LIBRARIES:
            value = 1.40 if completed in {'django', 'sqlalchemy'} else 0.65
    return (document, position + 1, (tail + token)[-384:]), float(value)

programs.haiku:
"""Python-code detector for one layer-0 MLP direction.

It fires on the end-of-document token <|endoftext|> (about 0.87 every time), and on
pieces of Python code: names of Python things (.py files, python, pytest, django,
setuptools, mock, ...; 0.5 to 1.9), Python keywords and dunder names (import, True,
False, __; about 0.35 to 0.5), exception class names (ValueError, KeyError, ...; about
0.5), and test-path pieces (/test, /tests, tests; about 0.3). Everything else
(prose, digits, punctuation, spaces) predicts 0.
"""

import re

READS = ()

END_OF_TEXT = "<|endoftext|>"
PYTHON_NAMES = {
    "py", "python", "pytest", "django", "jango", "setuptools", "uptools", "pip",
    "mock", "tqdm", "boto", "beautifulsoup", "matplotlib", "tempfile", "pathlib",
    "shutil", "unittest",
}
PYTHON_KEYWORDS = re.compile(r"^(import|True|False|None|isinstance|hasattr|getattr|kwargs|defaultdict)$")
DUNDER = re.compile(r"__")
EXCEPTION = re.compile(r"^\w*(Error|Exception)$")
TEST_PATH = {"test", "tests", "testcase", "tester"}


def value_of(s):
    if s == END_OF_TEXT:
        return 0.87
    word = s.strip().lower().strip("./_")
    if word in PYTHON_NAMES:
        return 0.9
    if EXCEPTION.match(s.strip()):
        return 0.5
    if PYTHON_KEYWORDS.match(s.strip()):
        return 0.4
    if DUNDER.search(s):
        return 0.35
    if word in TEST_PATH and not s.startswith(" "):
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    return carry, value_of(prefix.token_strings[-1])

