programs.sol:
"""Detect document separators and quotation-like delimiters.

Quotes adjoining Han text are much stronger than spaced European quotes.
Recognize curly and East Asian quotation marks, quoted list/object openings,
and escaped double quotes. Standalone ASCII quotes usually have a small
negative value outside Han text. Everything else is zero. The only memory
is the last token and 80 recent characters, reset at each document boundary.
The constants are training estimates; word-specific variation is omitted.
"""
READS = ()

# Quote glyph: (after Han letters, in recent Han text, elsewhere).
OPEN_QUOTES = {
    '“': (4.34, 2.3, 0.28),
    '‘': (3.78, 2.3, 0.48),
    '「': (3.3, 2.35, 2.35),
    '『': (1.77, 1.3, 1.3),
    '《': (1.67, 1.15, 1.15),
    '【': (0.68, 0.68, 0.68),
}
# A Chinese punctuation mark and an opening quote fused into one token.
PUNCTUATED_QUOTES = {
    '，“': 4.48,
    '、“': 3.77,
    '。“': 3.18,
    '：“': 2.28,
    '、「': 2.8,
    '。「': 2.1,
    '，《': 2.03,
}


def script(text, first, last):
    return any(first <= c <= last for c in text)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    previous, recent = ('', '') if fresh else carry[1:]
    carry = (doc, token, (recent + token)[-80:])
    if token != '<|endoftext|>' and not any(
            c in token for c in '"\'“‘„«”»「」『《【`'):
        return carry, 0.0
    han = script(previous, '\u3400', '\u9fff')
    han_context = script(recent, '\u3400', '\u9fff')
    cyrillic = script(recent, '\u0400', '\u052f')
    letters = any(c.isalpha() for c in previous)
    value = 0.0
    if token == '<|endoftext|>':
        value = 2.0 if han_context else 1.86
    elif token in PUNCTUATED_QUOTES:
        value = PUNCTUATED_QUOTES[token]
    elif token in OPEN_QUOTES:
        value = OPEN_QUOTES[token][0 if han else 1 if han_context else 2]
        if fresh and token in ('“', '‘'):
            value = 2.2
        elif script(previous, '\u3040', '\u30ff'):
            value = 3.25 if token == '“' else 2.6 if token == '「' else value
    elif token in (' «', '«'):
        value = 1.5 if cyrillic else 0.9
    elif token in (' “', ' ‘', ' „'):
        value = 2.2 if han_context else (
            1.2 if cyrillic else 0.64 if letters else 0.44)
        if token != ' “' and not han_context:
            value = 0.38 if token == ' ‘' else 0.3
    elif token == '”':
        value = 0.88 if han else 0.55 if han_context else 0.0
    elif token.startswith('」'):
        value = 0.7 if han else 0.53
    elif token in ('。”', '！”', '？”'):
        value = 0.76
    elif token == '»':
        value = 0.25
    elif '\\"' in token:
        before, after = token.split('\\"', 1)
        value = 0.4 if after else (
            1.04 if '(' in before or '=' in before else
            1.4 if '{' in before or ':' in before else
            0.93 if before.startswith(' ') else 0.81)
    elif token.endswith(('"', "'")):
        opening = token[:-1]
        if opening.endswith(('[', '{')):
            value = 0.7 if opening == ' {' else 0.88
        elif opening.endswith('('):
