CARRY_FORMS = {'carried', 'carrying', 'carries'}
CARRIERS = {'carrier', 'carriers'}
HOLD_FORMS = {'hold', 'held', 'holds', 'holding', 'handheld'}
CARRY_ENDINGS = {'ry', 'rying', 'ried', 'rier', 'riers', 'ries', 'arry'}
BEARING = {'bearing', 'borne', '-bearing', 'carriage', 'harness', 'wield'}
CONTAINERS = {'cargo', 'suitcase', 'basket', 'portable', 'burden', 'burdens',
