def lexical(token):
    word = token.strip()
    lower = word.lower()
    bare = lower.lstrip('._(')
    if lower == 'carry':
        return -4.9 if token.startswith(' ') else -3.8
    if lower in CARRY_FORMS:
        return -4.2
    if lower in CARRIERS:
        return -3.55
    if bare in {'payload', 'payloads'}:
        return -3.2 if word.startswith('(') else -4.25
    if bare in HOLD_FORMS:
        return -1.15
    if lower in {'holder', 'holders', 'holdings'} or lower.endswith('holder'):
        return -0.8
    if lower in BEARING:
        return -1.4 if lower == 'bearing' else -1.1
    if lower in {'bear', 'bears'}:
        return -0.95
    if lower in {'backpack', 'trailer', 'trailers'}:
        return -0.95
    if lower in {'cartridge', 'cartridges', 'holster'}:
        return -1.25
    if lower in CONTAINERS or lower in CONVEYING:
        return -0.55
    if lower == 'car':
        return -0.9 if word == 'Car' else -0.3
    if lower in CARRY_ENDINGS:
        if lower == 'arry':
            return -1.15
        return -0.35 if lower in {'ry', 'ries'} else -0.5
    if lower == 'arrier':
        return -1.8
    return CARRY_TRANSLATIONS.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, previous_value = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, previous_value = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical(token)
    # When a byte token finishes a carry/hold character, recognize the glyph.
    if '\ufffd' in token:
        last_character = prefix.text_prefixes[-1][-1:]
        if last_character in CARRY_TRANSLATIONS:
            value = CARRY_TRANSLATIONS[last_character]
    # Distinguish carrying from common compound senses of the same character.
    before = previous[-1:]
    if token == '携':
        value = -3.3 if before in {'提', '連', '连'} else -4.85
    elif token == '载':
        value = -0.55 if before == '下' else -2.4
    elif token == '載':
        value = -1.1 if before == '記' else -1.65 if before == '掲' else -2.1
    elif token == '持':
        value = -0.1 if before == '支' else -0.8 if before == '維' else -1.45
    if previous.lower().endswith('car') and word in CARRY_ENDINGS:
        value = -3.4 if word in {'rier', 'riers'} else -4.0
    elif word in {'the', 'a', 'an', 'by', 'of'} and previous_value < -0.8:
        value += previous_value * (0.28 if word == 'of' else 0.125)
    if token == '<|im_end|>' or token == '</think>':
        value = -0.11
    elif token == '<|im_start|>':
        value = 0.09
    elif token in {'</tool_call>', '</tool_response>'}:
        value = 0.21
    return (doc, token, value), value

