"""Layer-0 MLP down_proj component 5438: a word-level rule for its activation.

What it does: this component is small and diffuse. Most of its variance is a
token-specific signal spread over thousands of tokens, which no short list captures.
Its repeatable, interpretable part is on a few function words:

  * 'of' right after 'ahead' is strongly negative (about -0.6). Other 'of' after place,
    order, position or ownership nouns ('course of', 'opposite of', 'position of',
    'country of', 'list of') are negative (about -0.2).
  * 'of' after part or quantity nouns ('all of', 'heart of', 'factor of', 'fraction of',
    'kind of', 'rate of') is positive (about +0.2).
  * Object pronouns right after verbs of allowing, providing or helping ('allows us',
    'provide you', 'help me') are negative (about -0.25).
  * 'to' after an adjective such as 'difficult', 'available' or 'prior' is negative
    (about -0.15).

Everything else predicts 0. Values are shrunk to 0.75 of these, since the signs of the
weaker groups are not reliable. Measured on training rows, this explains about 2% of
the activation variance; a per-token table would add more, but it would be arbitrary.
"""

READS = ()
SCALE = 0.75

AHEAD = {"ahead"}
PLACE_ORDER_OF = {
    "course", "opposite", "position", "place", "way", "country", "list", "set",
    "collection", "combination", "ownership", "writer", "majority", "variety", "regardless",
    "capable",
}
QUANTITY_OF = {
    "all", "half", "best", "heart", "factor", "fraction", "kind", "sign", "sense", "loss",
    "rate", "use", "period", "model", "expression", "lot",
}
GIVING_VERBS = {
    "allow", "allows", "allowed", "provide", "provides", "provided", "help", "helps",
    "enable", "enables", "offer", "offers",
}
OBJECT_PRONOUNS = {" you", " us", " me", " them"}
ADJ_TO = {"difficult", "available", "prior", "adjacent", "ready", "impossible", "able"}


def rule(tok, prev):
    """The predicted activation for token `tok` right after word `prev`."""
    if tok == " of":
        if prev in AHEAD:
            return -0.6
        if prev in PLACE_ORDER_OF:
            return -0.2
        if prev in QUANTITY_OF:
            return 0.2
    if tok in OBJECT_PRONOUNS and prev in GIVING_VERBS:
        return -0.25
    if tok == " to" and prev in ADJ_TO:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    return carry, SCALE * rule(prefix.token_strings[-1], prev)

programs.sol:
"""Predict a spelling response strongest on short double-L fragments.

'Call' and the -all rhyme family dominate. Other short double-L words,
and a few weaker short-word rhyme families, get smaller values. Whole
fragments are matched: 'wall' responds much more than 'wallet'. Case,
spacing and inflections adjust the estimate; split-off 'all' consults
the preceding fragment. Document boundaries reset that context. Small
fixed responses also cover thinking and end-of-message markers.
"""
import re

READS = ()

# Short double-L spelling families.
RHYMES = (
    (r'call', 0.77),
    (r'[bghvw]all', 0.67),
    (r'[mpt]all', 0.51),
    (r'fall', 0.26),
    (r'[bdgj]ill|[bd]ell|doll', 0.33),
    (r'[hm]ill|pill|[pt]oll|[bhm]ull', 0.22),
    (r'fell', 0.17),
    (r'[fk]ill|sell|tell|roll|full', 0.10),
)
PATTERNS = [(re.compile(r'(' + pattern + r')(s|ed|ing|er)?$'), value)
            for pattern, value in RHYMES]
ENDING_SCALE = {'': 1.0, 's': 0.84, 'ed': 0.15, 'ing': 0.70, 'er': 0.50}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    fragment = token.strip().lstrip('._-(/')
    word = fragment.lower()
    value = 0.0
    for pattern, base in PATTERNS:
        match = pattern.fullmatch(word)
        if match:
            scale = ENDING_SCALE[match[2] or '']
            value = base * scale
            if fragment[:1].isupper():
                value += 0.08 * scale
            if word.startswith('call') and not token.startswith(' '):
                value += 0.07 * scale
            if word.startswith('fall') and not token.startswith(' '):
                value += 0.17 * scale
            break
    if token.lower() in ('all', 'alls', 'alli', 'alla', 'aller', 'alled', 'alling'):
        # When tokenization splits a word immediately before 'all'.
        stem = previous
        if not stem or not stem[-1:].isalpha():
            value = 0.15
        elif stem[-1:].lower() == 'w':
            value = 0.77
        elif stem[-1:].lower() in 'hb':
            value = 0.60
        elif stem[-1:].lower() in 'gvy':
            value = 0.47
        else:
            value = 0.30
        if len(word) > 3:
            value *= 0.8
    if value == 0.0 and 3 <= len(word) <= 5 and word.isascii():
        # Weaker short-word spelling families, including liquid consonants
        # (L/R) followed by a stop, nasal, or fricative at the word's end.
        if re.fullmatch(r'[a-z]{0,2}(old|ead|ock|uck)', word):
            value = 0.09
        elif re.fullmatch(r'[a-z]{1,3}[lr][bdgkmpstf]', word):
            value = 0.05
        elif re.fullmatch(r'[a-z]{1,2}(and|ind|ail|art|ish)', word):
            value = 0.05
    if word in ('oll', 'ull', 'yll', 'äll'):
        value = 0.17
    if token in ('<think>', '</think>'):
        value = 0.12
    elif token == '<|im_end|>':
        value = -0.06
    return (doc, token), float(value)

programs.haiku:
"""Draft 3: one-syllable words that rhyme with "call" / "bell" (onset + -all, -ell, -ill).

The component fires on the word itself, not on a context: "call", "ball", "wall", "hall",
"tall" are strong; "fall" is weaker; "bell", "bill", "mill", "hill", "kill" are moderate.
Compounds (football, baseball), the word "all", and inflections such as "called" stay near
zero.
"""
READS = ()

STRONG = {"call", "calls", "ball", "balls", "wall", "walls", "hall", "tall", "gall"}
MEDIUM = {"bell", "bill", "gill", "mill", "hill", "kill", "calling"}
WEAK = {"fall", "falls", "falling"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
        return carry, 0.7
    if word in MEDIUM:
        return carry, 0.3
    if word in WEAK:
        return carry, 0.25
    return carry, 0.0
